export const EMBEDDED_SKILL_FILES: Readonly<Record<string, string>> = {
  "aspire/SKILL.md": "---\nname: aspire\ndescription: 'Diagnoses and operates Aspire distributed applications with the Aspire CLI — resource state, health reports, console logs, structured logs, spans and traces. USE FOR: a resource says Healthy but does not respond, an endpoint times out, a request fails and you do not know which service, the AppHost vanished, a resource is stuck Waiting/Starting, finding the port a resource actually bound, reading logs or traces, restarting one resource, aspire start/stop/describe/logs/otel/export/wait. DO NOT USE FOR: non-Aspire .NET apps (use dotnet CLI), container-only deployments (use docker/podman). INVOKES: aspire describe, aspire logs, aspire otel logs|spans|traces, aspire ps, aspire export, aspire resource, aspire wait, aspire doctor, aspire docs, bash. FOR SINGLE OPERATIONS: run the Aspire CLI command directly.'\n---\n\n# Aspire Skill\n\nThis repository uses Aspire to orchestrate its distributed application. Resources are defined in the\nAppHost (`aspire/apphost.mts`, or `apphost.cs` in .NET projects).\n\nThe Aspire CLI is a **diagnostic instrument**, not just a launcher. Statements explicitly tagged\nwith an S2 or S9 evidence key were re-verified against **Aspire CLI 13.5.3**; other operational\nguidance is not a blanket 13.5 certification. The evidence keys link to exact receipts at the end of\nthis skill. When something misbehaves, ask the CLI before touching application code. **Rule zero:\n`Healthy` is not proof.**\n\n## CLI command reference\n\nAppend `--non-interactive --nologo` to every command in an agent session: no spinners, no banners,\nno prompts, parseable output. Add `--format Json` when you need fields rather than a table.\n\n| Task                                                | Command                                                                      |\n| --------------------------------------------------- | ---------------------------------------------------------------------------- |\n| Start (or restart — it stops the previous instance) | `aspire start`                                                               |\n| Start isolated (worktrees, parallel agents)         | `aspire start --isolated`                                                    |\n| Stop one exact AppHost                              | `aspire stop --apphost <exact-AppHost-path>`                                 |\n| Force-stop one orphaned AppHost                     | `aspire stop --apphost <exact-AppHost-path> --force` (S2-V7)                 |\n| Running AppHosts + dashboard URL + PID + log path   | `aspire ps --format Json`                                                    |\n| Resource state, URLs, env, health reports           | `aspire describe [<resource>] --format Json`                                 |\n| Resource-state alias                                | `aspire resources [<resource>] --format Json` (S2-V11)                       |\n| Include Aspire infra resources · stream changes     | `aspire describe --include-hidden` · `--follow`                              |\n| Wait for a resource                                 | `aspire wait <resource> --status healthy --timeout 60`                       |\n| **Console logs (stdout/stderr)**                    | `aspire logs <resource> -n 200 -t` · `aspire logs --follow`                  |\n| **Structured logs**                                 | `aspire otel logs [<resource>] --severity Error -n 100`                      |\n| **Spans**                                           | `aspire otel spans [<resource>] --has-error`                                 |\n| **Traces**                                          | `aspire otel traces [<resource>] --has-error`                                |\n| Everything for one trace                            | `aspire otel spans --trace-id <id>` · `aspire otel logs --trace-id <id>`     |\n| Capture resources + logs + telemetry to a zip       | `aspire export -o /tmp/aspire.zip`                                           |\n| Start/stop/restart one resource                     | `aspire resource <resource> start\\|stop\\|restart`                            |\n| Environment diagnostics                             | `aspire doctor --format Json` (S2-V10)                                       |\n| Restore AppHost SDK + deps                          | `aspire restore`                                                             |\n| Add an integration / list AppHost files             | `aspire add` · `aspire ls`                                                   |\n| Docs                                                | `aspire docs search <query>` · `aspire docs get <slug>` · `aspire docs list` |\n| TypeScript API docs                                 | `aspire docs api search <query> --language typescript` (S9-DOCS-API-HELP)    |\n| Resource-exposed MCP tools                          | `aspire mcp tools` · `aspire mcp call <resource> <tool> --input <json>`      |\n\n`--apphost <path>` targets a specific AppHost when several run. There is no `aspire exec`.\n`aspire resources` is a 13.5.3 alias of `aspire describe`; singular `aspire resource` still operates\none resource. (S2-V11)\n\n## Rule zero: `Healthy` is not proof\n\n`healthStatus` is inferred from **process/container state** unless a health check is registered. A\nresource with no health checks reports `Healthy` the moment its process is alive — before it binds a\nport, and while every request to it times out.\n\nThe proof is in `healthReports`:\n\n```bash\naspire describe --format Json --non-interactive --nologo \\\n  | jq -r '.resources[] | \"\\(.displayName)\\t\\(.state)\\t\\(.healthStatus)\\treports=\\(.healthReports|length)\"'\n```\n\n```\ndashboard     Running  Healthy  reports=0   <- nothing was ever checked\nstreams       Running  Healthy  reports=0   <- nothing was ever checked\npostgres      Running  Healthy  reports=1   <- postgres_check actually ran\nhookline-db   Running  Healthy  reports=2   <- hookline-db_check, postgres_check\n```\n\n**`healthReports: {}` means no check ran.** In exactly this state the `dashboard` resource\nadvertised `http://localhost:42719` and every request timed out for ~30s while the label stayed\n`Healthy`. Treat `reports=0` as _unknown_ and go get evidence.\n\n## Diagnose by symptom\n\n### \"It says Healthy but nothing responds\"\n\n```bash\naspire describe <resource> --format Json --non-interactive --nologo   # healthReports, state, urls, environment\naspire logs <resource> -n 200 -t --non-interactive --nologo           # the most under-used command there is\naspire otel logs <resource> --severity Error --dashboard-url \"$DASH\" --non-interactive --nologo\n```\n\n`aspire logs` is console stdout/stderr exactly as the process wrote it — dev-server banners, bind\nerrors, stack traces. It works even when telemetry does not, because it arrives over the AppHost\nbackchannel rather than the dashboard. `--format Json` yields `{resourceName, content, isError}`;\n`isError: true` marks stderr.\n\n`aspire otel logs --severity Error` finds silent crashes. On a run where every resource read\n`Healthy`, it surfaced a full `initializeKv` stack trace and a\n`PostgreSQL is NOT reachable at\nlocalhost:5432` banner that no status column mentioned.\n\nTwo common non-bugs: a dev server (Vite, Next) still doing its first compile times out for tens of\nseconds while `Healthy` — retry before debugging; and the URL in `describe` is a proxy that forwards\nonly once the target binds. If neither log source explains it, probe the port the resource actually\nbound (next-but-one section).\n\n### \"A request fails and I do not know which service\"\n\nFollow one request end to end:\n\n```bash\naspire otel traces --has-error --format Json --non-interactive --nologo -n 10   # 1. which traces failed\naspire otel spans  --trace-id <traceId> --non-interactive --nologo              # 2. every span, in order\naspire otel logs   --trace-id <traceId> --non-interactive --nologo              # 3. log lines inside it\n```\n\nA span carries `traceId`, `spanId`, `parentSpanId`, `kind` (`Server`/`Client`/`Internal`), `name`,\n`source` (the emitting resource), `status`, `statusMessage`, `durationMs`, and `attributes`\n(`http.request.method`, `url.full`, `url.path`, `http.response.status_code`, `error.type`). Chain\n`parentSpanId` → `spanId` for the call graph; `source` changes at each hop, so a `Client` span in\nservice A next to a `Server` span in service B _is_ the network boundary. The failing span is the\ndeepest one with `status: Error` — its `url.full` and `error.type` name the exact call that broke.\n\nStructured log records carry `traceId` and `spanId`, so you can go the other way: find an error line\nwith `aspire otel logs --severity Error --format Json`, take its `traceId`, replay the whole\nrequest. Every trace and span also ships a `dashboardUrl` deep link.\n`aspire otel logs --trace-id <id>` printing `No logs found` is normal — that trace emitted spans but\nno correlated log records.\n\n### \"`aspire otel` says the dashboard is not available\"\n\nVerified 13.5.3 behavior on a detached AppHost: bare `aspire otel logs` exited 12 because the\ndashboard URL was unavailable to the command, while the same query succeeded when passed the\nrecorded URL with `--dashboard-url`. Pass the URL explicitly. (S2-V4)\n\n```bash\nDASH=$(aspire ps --format Json --non-interactive --nologo | jq -r '.[0].dashboardUrl')\naspire otel traces --dashboard-url \"$DASH\" --non-interactive --nologo\n```\n\n**Never conclude telemetry is unavailable until you have retried with `--dashboard-url`.** The URL\nis also in `aspire describe aspire-dashboard --include-hidden --format Json`. `--api-key` exists for\ndashboards with API-key auth.\n\n### \"Something answers the URL, but is it mine?\"\n\n`describe` advertises the endpoint the AppHost _intended_. If a fixed port was already taken by a\nforeign process, Aspire logs nothing, the URL still appears, and the foreign process answers —\nhealthily — with somebody else's application. Reproduced here: `streams` advertised\n`http://localhost:4437`; stopping the resource left `4437` still returning\n`{\"status\":\"healthy\",\"version\":\"1.0.0\"}` while the real service on its own port went dark.\n\n```bash\naspire describe <resource> --format Json --non-interactive --nologo \\\n  | jq '.resources[0] | {url: [.urls[].url], port: .environment.PORT, pid: .properties[\"executable.pid\"]}'\n# => {\"url\":[\"http://localhost:4437\"], \"port\":\"42117\", \"pid\":552186}\n\nss -ltnp | grep -E ':(4437|42117) '\n# 42117 -> deno pid 552186  == the resource's own pid  -> yours\n# 4437  -> no listener at all, yet curl answers        -> foreign / out-of-namespace process\n```\n\n**`urls[].url` is the Aspire (DCP) proxy port; `environment.PORT` is the port the app itself bound**\n— they differ. A proxy port owned by `dcp` in front of the resource's own PID is genuinely yours. A\nport that responds with **no listener** `ss`/`lsof` can attribute is not in your process tree — on\nWSL usually a Windows-side or other-namespace process; compare an identity field (`/health`,\n`/version`) against the resource's own port to confirm. `aspire start --isolated` randomizes ports\nand removes this failure class entirely.\n\n### \"A resource will not start, or is stuck Waiting/Starting\"\n\n`Waiting` means an upstream dependency has not gone healthy — fix the dependency, not the resource.\nWatch the graph converge instead of polling: `aspire describe --follow`, or block on one resource\nwith `aspire wait <resource> --status healthy --timeout 60`.\n\nFor a stopped resource, `state` becomes `Finished`, `healthStatus` becomes `null`, and `exitCode` +\n`stopTimestamp` populate (`exitCode: -1` = killed). `aspire logs <resource>` retains the dead\nprocess's output — read it before restarting.\n\n### \"The AppHost is gone\"\n\n`aspire ps --format Json --non-interactive --nologo` returning an empty array means nothing is\nrunning — something stopped it (another `aspire start`, the host-wide stop mode, or a tool that\ntakes over the AppHost's port, e.g. a database CLI command). When one _is_ running it returns\n`appHostPath`, `appHostPid`, `cliPid`, `sdkVersion`, `dashboardUrl` and **`logFilePath`** — the\nAppHost's own log, which explains startup and shutdown when resource logs cannot.\n\nWith no AppHost running, command output may be informational rather than a health verdict. Check\n`aspire ps` first; the S2/S9 receipts did not re-verify the complete no-AppHost exit-code set.\n\n### \"`aspire restore` / `aspire start` is hanging\"\n\nMeasured 13.5.3 observations on the S2 host were **38.62s** for a cold start, **24.80s** for the\nsecond start, and **13.065s** for the isolated scratch restore. Treat these as bounded observations,\nnot portable performance guarantees. (S2-V2, S2-V9) Before waiting out a multi-minute operation, run\n`aspire doctor --non-interactive\n--nologo` (container runtime, SDK, certs, WSL integration) and\n`docker ps`.\n\n### Capture everything before you lose it\n\nUse `aspire export --help` to inspect the current export options before capturing an intermittent\nfailure or preparing a handoff. The S2/S9 receipts did not re-verify archive contents or behavior\nwhen `--dashboard-url` is omitted.\n\n## Search and filter syntax\n\nSearch grammar differs across console logs and structured telemetry commands. Run the relevant\n`aspire logs --help` or `aspire otel logs|spans|traces --help` before composing filters; the S2/S9\nreceipts did not re-verify the full search grammar.\n\n## Aspire MCP tools\n\nThe Aspire MCP server is launched in AppHost mode as `aspire agent mcp`; that exact argv was\nobserved in the 13.5.3 JSON-RPC capture. For dashboard-only mode, use\n`aspire agent mcp --dashboard-url <dashboard-url>`; add `--api-key <api-key>` only when that\ndashboard requires API-key authentication. (S9-STATIC, S9-AGENT-MCP-HELP) It exposes the same data\nwithout shelling out. **It is often not connected** — if these tools are absent from your tool list,\nuse the CLI. The 13.5.3 static receipt observed these 14 tools (S9-STATIC):\n\n| Tool                                           | Args                                       | Use it for                                                   |\n| ---------------------------------------------- | ------------------------------------------ | ------------------------------------------------------------ |\n| `list_resources`                               | —                                          | state, health, `health_reports`, urls, commands (snake_case) |\n| `list_console_logs`                            | `resourceName`, `search`                   | why a resource is not running                                |\n| `list_structured_logs`                         | `resourceName`, `search`                   | errors carrying `trace_id`/`span_id`                         |\n| `list_traces`                                  | `resourceName`, `search`                   | which traces failed                                          |\n| `list_trace_structured_logs`                   | `traceId`, `search`                        | drill into one trace                                         |\n| `execute_resource_command`                     | `resourceName`, `commandName`, `arguments` | start/stop/restart a resource                                |\n| `list_apphosts` / `select_apphost`             | — / `appHostPath`                          | disambiguate multiple AppHosts                               |\n| `doctor`, `list_integrations`, `refresh_tools` | —                                          | environment checks, integrations, surface refresh            |\n| `search_docs`, `get_doc`, `list_docs`          | `query` / `slug`                           | aspire.dev documentation                                     |\n\nThe required 13.5.3 baseline is the 14 tools above. `get_integration_docs` is documented but was\nunobserved in both the S2 live capture and S9 static capture; its absence and later appearance are\ninformational, not a smoke-gate failure. (S2-V8, S9-STATIC)\n\nThere is no MCP tool for spans — use `aspire otel spans` for span-level detail. **Use the CLI over\nMCP when you need environment variable values:** `list_resources` returns env var _names with null\nvalues_ (redacted), so `PORT` — the field that proves which port a resource actually bound — is\navailable only from `aspire describe --format Json`. `aspire mcp tools` / `aspire mcp call` are\nunrelated: they list MCP tools that **resources** expose (e.g. `WithPostgresMcp()` adds SQL query\ntools), and report `No resources with MCP tools found` when none do.\n\n## Applying code changes\n\n| What changed                              | Action                           | Why                                               |\n| ----------------------------------------- | -------------------------------- | ------------------------------------------------- |\n| AppHost (`apphost.mts`/`apphost.cs`)      | `aspire start`                   | Resource graph changed; full restart required     |\n| Compiled .NET project resource            | `aspire resource <name> rebuild` | Rebuild + restart that resource only              |\n| Interpreted resource (TypeScript, Python) | usually nothing — file watchers  | `aspire resource <name> restart` if no watch mode |\n\n**Never restart the whole AppHost because one resource changed.** Which commands a resource supports\nis data, not a guess — `jq -r '.resources[] | \"\\(.displayName)\\t\\(.commands|keys|join(\",\"))\"'` over\n`aspire describe --format Json`. Executables and containers typically expose only `restart,stop`\n(and `start` once stopped); `rebuild` exists only on .NET project resources. Calling a command a\nresource lacks fails loudly: `Command 'rebuild' not available for resource 'users'.`\n\n## Important rules\n\n- **Never kill an `aspire agent mcp` process.** Those are the session's MCP servers, not stray\n  AppHosts.\n- **`Healthy` with `healthReports: {}` is not evidence.** Get console logs, structured logs, or a\n  probe against the resource's own port.\n- **To restart, just run `aspire start` again** — it stops the previous instance. Never\n  `aspire stop` then `aspire run`, and never `aspire run` in an agent session (it is\n  interactive/foreground).\n- **Use `--isolated`** in worktrees or when another agent may be running.\n- **Clean up only the AppHost you started**: take its exact `appHostPath` from `aspire ps`, then run\n  `aspire stop --apphost <exact-AppHost-path> --non-interactive --nologo`. Use\n  `aspire resource <name> stop` when targeted cleanup is enough, then check `docker ps`. The\n  host-wide `aspire stop` mode with `--all` is both unsafe and unreliable on a shared host: it has\n  reported `No running AppHost found` and exited 0 while processes rooted at the AppHost survived.\n  Three independent agents observed that failure in one night. `dcp` helper processes take ~20s to\n  exit after a scoped stop returns, so re-check rather than killing them. Leave pre-existing\n  containers alone — Aspire reuses persistent ones and deleting them destroys another session's\n  data.\n- **Use `--force` only for the exact orphan you own.** Aspire 13.5.3 automatically removes an\n  orphaned launcher registration after its process dies; if it persists, scoped\n  `aspire stop --apphost <path> --force` clears it without broad host cleanup. (S2-V6, S2-V7)\n- **Prefer `aspire logs` / `aspire otel` over hand-rolled `curl` probing.** A `curl` timeout tells\n  you nothing about why; the failing span names the exact call that broke.\n- **Prefer `aspire docs search <query>` / `aspire docs get <slug>`** over searching package caches;\n  it serves current content from aspire.dev.\n- **Avoid persistent containers** early in development, and **never install the Aspire workload** —\n  it is obsolete.\n\n## Playwright CLI\n\nIf configured, use Playwright CLI for functional testing of resources. Get endpoints from\n`aspire describe --format Json` — and verify the port is yours, per above — rather than assuming a\ndefault. Run `playwright-cli --help` for available commands.\n\n## 13.5.3 evidence\n\n- S2-MATRIX:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/aspire-13.5-verification.md`\n- S2-V4:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/02-v4-otel-bare.raw.txt`\n  and `02-v4-otel-explicit.json`\n- S2-V2:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/02-runtime-lifecycle.md`\n- S2-V9:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/03-v9-aspire-restore.time.txt`\n- S2-V6:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/02-v6-aspire-ps-final.json`\n- S2-V7:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/02-v7-aspire-stop-force.raw.txt`\n- S2-V8:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/03-v8-mcp-summary.json`\n- S2-V10:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/03-v10-doctor.json`\n- S2-V11:\n  `origin/test/aspire-13-5-s2-runtime-verification:.llm/runs/test-aspire-13-5-s2-runtime-verification--impl/receipts/03-v11-resources-alias.json`\n- S9-STATIC:\n  `d8187e5a8656de8f9443f4e33f0a91ece56a7dd2:.llm/runs/fix-aspire-13-5-s9-skills-mcp-alignment--impl/receipts/aspire-13.5.3-mcp-tools-static.json`\n- S9-DOCS-API-HELP:\n  `d8187e5a8656de8f9443f4e33f0a91ece56a7dd2:.llm/runs/fix-aspire-13-5-s9-skills-mcp-alignment--impl/receipts/aspire-13.5.3-docs-api-search-help.json`\n- S9-AGENT-MCP-HELP:\n  `d8187e5a8656de8f9443f4e33f0a91ece56a7dd2:.llm/runs/fix-aspire-13-5-s9-skills-mcp-alignment--impl/receipts/aspire-13.5.3-agent-mcp-help.json`\n\n### Upstream cleanup of networks and anonymous volumes (issue #1855)\n\nStopping an AppHost — `aspire stop`, or the AppHost exiting — tears down its DCP session, and DCP's\nown cleanup controller then reaps Aspire-managed Docker resources it considers abandoned, including\n`aspire-persistent-network-*` networks. That reap is keyed on DCP metadata inside the Aspire\nruntime, not on the calling process, so a foreign run's persistent network can be removed as\ncollateral while stopping your own AppHost. Cleanup code that removes only containers cannot prevent\nor intercept this from inside `aspire stop`; the mitigation is detection, not prevention:\n\n- Before cleanup, enumerate DCP-managed networks by the `com.microsoft.developer.usvc-dev.*` label\n  namespace, never by name pattern, and flag the ones your run cannot positively own as at-risk.\n  Keep that list as the record of what existed before cleanup; a network is never a cleanup target.\n- Remove owned containers with `docker rm -f -v`, so the run's anonymous volumes die with their\n  containers while named volumes always survive. Report run-owned volumes that remain as survivors.\n- Upstream references: the aspire.dev networking overview (persistent vs session networks),\n  `dotnet/aspire#9785`, `dotnet/aspire#13320`, and `microsoft/dcp#213` (workload-scoped persistent\n  resource cleanup).\n",

  "deno/SKILL.md": "---\nname: deno\ndescription: \"Diagnostic instrument for the Deno runtime and toolchain. Reach for it the moment something is wrong and you do not know why. USE FOR: a process that exits silently or hangs, a dev server that 'died', type errors the editor does not show (or shows and the CLI does not), 'Import X not a dependency', unresolved/stale modules, permission denials, leaking or hanging tests, lockfile and dependency-age failures, reading a package's API. DO NOT USE FOR: Fresh/Preact/islands/Tailwind authoring (follow the project's Fresh documentation and conventions); NetScript release/dependency policy (follow the repository's checked-in release and dependency tooling). INVOKES: deno check, deno info, deno task, deno test, deno lint, deno fmt, deno doc, deno coverage, deno bench, deno clean, deno add/install/outdated/why, bash. Verified on Deno 2.9.3 — re-verify flags on other versions.\"\n---\n\n# Deno Toolchain Diagnostics\n\n**The runtime will tell you what is wrong. Ask it.** Every symptom below has a command that answers\nit in seconds. Guessing, re-running, and re-reading source is what burns hours.\n\nEverything here was executed on **Deno 2.9.3** (`deno --version`). Behaviour marked _(2.9)_ is\nversion-sensitive — re-check with `deno <cmd> --help` before trusting it on another release.\n\n## The exit-code trap — read this first\n\n**A pipeline reports the _last_ stage's status.** Verified: `deno check main.ts` exits 1; but\n\n```bash\ndeno check main.ts | tail -1   # -> prints \"error: Type checking failed.\"  and exits 0\n```\n\nThis is true whether you pipe on the command line **or bake the pipe into a `deno.json` task** — a\ntask defined as `\"check\": \"deno check main.ts | tail -1\"` reports exit 0 while type checking fails.\n\nFixes, in order of preference: **do not pipe**; or `set -o pipefail`; or read `${PIPESTATUS[0]}`.\n\nThree more sources of a lying exit 0, all verified:\n\n| Command                                         | Silent success                                            | Why                                                                                                                                           |\n| ----------------------------------------------- | --------------------------------------------------------- | --------------------------------------------------------------------------------------------------------------------------------------------- |\n| `deno check <path excluded by deno.json>`       | prints `Warning No matching files found.` and **exits 0** | `deno lint` / `deno fmt --check` / `deno test` instead print `error: No target files found.` and exit **1**. `deno check` is the odd one out. |\n| `deno run file.ts` on a file with type errors   | runs and exits 0                                          | `deno run` does **not** type-check. Use `deno check`, or `deno run --check`.                                                                  |\n| `deno info file.ts` with an unresolvable import | prints `(resolve error)` and **exits 0**                  | Read the tree, not the code.                                                                                                                  |\n\n**Rule: verify the artefact, never the exit code.** Did the file appear, did the port open, did the\ntype error text vanish. Generators, installers and builds all exit 0 while producing nothing.\n\nIn an initialized NetScript project, use\n`deno run --allow-read --allow-run .llm/tools/run-deno-check.ts --root <path> --pretty`. It\nenumerates explicit inputs, reports `selection.filesSelected`, and fails when selection is empty,\nclosing the excluded-file exit-0 trap.\n\n## CLI command reference\n\n| Task                                                       | Command                                                            |\n| ---------------------------------------------------------- | ------------------------------------------------------------------ |\n| Type-check the whole project (honours `include`/`exclude`) | `deno check`                                                       |\n| Type-check one file + its graph                            | `deno check path/to/file.ts`                                       |\n| Type-check a file the config excludes                      | `deno check --no-config path/to/file.ts`                           |\n| Also type-check npm/remote deps                            | `deno check --all <file>`                                          |\n| Show the resolved module graph                             | `deno info <file-or-specifier>`                                    |\n| Machine-readable graph + on-disk paths                     | `deno info <specifier> --json`                                     |\n| Show `DENO_DIR` and every cache location                   | `deno info` (no args)                                              |\n| Who pulls in a package                                     | `deno why <pkg>`                                                   |\n| List tasks                                                 | `deno task` (no args)                                              |\n| Lint                                                       | `deno lint` / `--compact` / `--json` / `--rules`                   |\n| Format check (diff + exit 1)                               | `deno fmt --check`                                                 |\n| Run tests                                                  | `deno test [--filter <s>] [--fail-fast[=N]] [--reporter=dot]`      |\n| Tests touching a file / changed files                      | `deno test --related=<file>` / `deno test --changed`               |\n| Catch leaks _(2.9: opt-in)_                                | `deno test --sanitize-ops --sanitize-resources [--trace-leaks]`    |\n| Coverage                                                   | `deno test --coverage=cov` then `deno coverage cov --detailed`     |\n| Benchmarks                                                 | `deno bench [--filter <s>] [--json]`                               |\n| Public API of a module                                     | `deno doc <specifier>` / `--filter <Symbol>` / `--lint <files...>` |\n| Re-fetch one dependency                                    | `deno check --reload=npm:<pkg> <file>`                             |\n| See what a cache wipe would cost                           | `deno clean --dry-run`                                             |\n| Debugger                                                   | `deno run --inspect-brk <file>` / `--inspect-wait`                 |\n| Op-level trace                                             | `deno run --trace-ops=<op,op> <file>`                              |\n| Verbose runtime log                                        | `deno run -L debug <file>`                                         |\n\n**Always prefix `NO_COLOR=1`** when you will read or grep the output. Deno emits ANSI escapes even\nwhen stdout is redirected to a file — verified with `od -c` on `deno doc > file`.\n\n## Key workflows\n\n### Debugging issues\n\nMatch the symptom, run the command, read the named field.\n\n**\"The process exits with no output\" / \"the dev server died silently.\"**\n\n1. Stop backgrounding it. Run it in the foreground and keep stderr:\n   `deno task dev > /tmp/dev.log 2>&1; echo \"exit=$?\"` — never `| tee`, that eats the exit code.\n2. Read the exit code. `0` = nothing kept the event loop alive (an aborted `AbortController`, a\n   server that never listened). `1` = uncaught error, and the text is on **stderr**. `124` = your\n   own `timeout`. `137` = SIGKILL / OOM.\n3. Port conflicts look like\n   `error: Uncaught (in promise) AddrInUse: Address already in use\n   (os error 98)` — stderr only.\n   If you discarded stderr you saw \"silent\".\n4. Still opaque: `deno run -L debug <entry>`. It logs every module load, V8 code-cache hit, and ends\n   with `received module evaluate Ok(())` — that line proves the module evaluated, so the problem is\n   after evaluation, not in resolution.\n5. Attach a debugger: `--inspect-brk` (break at first line) or `--inspect-wait` (wait for a client,\n   then run). Both default to `127.0.0.1:9229`.\n\n**\"It hangs.\"** `deno run --trace-ops=op_timer_schedule,op_read <file>` — bare `--trace-ops` is a\nflood, always pass the comma-separated filter. Look for a `Dispatched` with no matching `Completed`.\n\n**\"Type errors, but the editor is fine\" (or the reverse).** The editor is the LSP: it checks only\nopen files. `deno check` follows real module graphs and obeys `deno.json`.\n\n- `deno check` (no args) checks **every** project file — the editor never does this.\n- `deno check file.ts` checks _only that file and what it imports_. A task defined as\n  `deno check main.ts` proves nothing about the other 200 files.\n- If `deno check <file>` says `Warning No matching files found.`, the path is **excluded** in\n  `deno.json`. Re-run with `--no-config` to check it anyway.\n- Errors inside npm/remote packages are skipped by default; `deno check --all <file>` includes them.\n\n**\"Type errors from generated code\" (Prisma client, codegen output).** Generated directories are\nalmost always in `exclude`, so plain `deno check` skips them and `deno check <that file>` exits 0\nsilently. Do both of these before touching the generator:\n\n```bash\nNO_COLOR=1 deno check --no-config path/to/generated/client.ts   # the real diagnostics\nNO_COLOR=1 deno info path/to/generated/client.ts                # which .d.ts is actually loaded\n```\n\n**`Import \"zod\" not a dependency and not in import map`.** This is not a framework bug. It is\nresolution. `deno check` already prints the fix as a hint (`try running deno add npm:zod`). Confirm\nwith the graph:\n\n```bash\nNO_COLOR=1 deno info src/thing.ts\n# └── Import \"zod\" not a dependency ...  (resolve error)     <- unresolved edge\n# └── npm:/zod@4.4.3 (4.35MB)                                <- resolved edge\n```\n\n`deno info <specifier> --json` gives `npmPackages[\"zod@4.4.3\"].localPath` — the exact directory in\nthe cache. Read the real `.d.ts` there instead of guessing at the types.\n\n**\"A permission error.\"** Deno names the capability _and_ the exact resource:\n`NotCapable: Requires env access to \"HOME\", run again with the --allow-env flag`. Grant the\nnarrowest thing that satisfies it — `--allow-env=HOME`, `--allow-read=./data`,\n`--allow-net=127.0.0.1:8000`. Scoping is literal: `--allow-net=example.com` does **not** permit\nbinding `0.0.0.0:8124`. In non-interactive/agent runs add `--no-prompt` (or `DENO_NO_PROMPT=1`) so a\nmissing permission fails immediately instead of blocking on an invisible prompt.\n`DENO_TRACE_PERMISSIONS=1` adds stack traces.\n\n**\"A test hangs or leaks.\"** _(2.9)_ **Ops and resource sanitizers are off by default since 2.8** —\na test that leaves a timer or an open file passes. Turn them on:\n\n```bash\ndeno test --sanitize-ops --sanitize-resources          # or DENO_TEST_SANITIZE_OPS=1\ndeno test --sanitize-ops --trace-leaks                 # adds the stack where the leak started\n```\n\n`--trace-leaks` turns `A timer was started in this test, but never completed` into the exact source\nline. Narrow the run with `--filter <substring-or-regex>`, `--fail-fast`, `--related=<file>` (note\nthe `=`; a space errors), or `--changed` (needs a git repo). `--no-run` type-checks the test files\nwithout executing them. `--reporter=dot` for compact output.\n\n**\"It worked yesterday\" / stale-cache suspicion.**\n\n```bash\nNO_COLOR=1 deno info                       # DENO_DIR + remote / npm / gen cache paths\ndeno check --reload=npm:<pkg> <file>       # re-fetch ONE dep; `npm:` alone reloads all npm\nDENO_DIR=/tmp/deno-probe deno check <file> # reproduce against a pristine cache, destroys nothing\ndeno clean --dry-run                       # \"Removed <dir> (728938 files, 13.88GB)\" then aborts\n```\n\nPrefer an isolated `DENO_DIR` over `deno clean`. `deno clean` wipes the whole shared cache;\n`deno clean -e <files>` retains what those files need.\n\n### Verifying a change\n\nRun the smallest command that proves it, and read the output rather than the status:\n\n```bash\nNO_COLOR=1 deno check                    # every project file\nNO_COLOR=1 deno lint --compact           # one line per problem\nNO_COLOR=1 deno fmt --check              # unified diff of what would change\nNO_COLOR=1 deno test --fail-fast\n```\n\n`deno lint --rules` lists all ~120 rules with tags; `--rules-include` / `--rules-exclude` /\n`--rules-tags` adjust the set; `--json` is stable for scripting.\n\n### Coverage and performance\n\n```bash\ndeno test --coverage=cov            # prints the summary table AND writes cov/lcov.info + cov/html\ndeno coverage cov --detailed        # per-file %, then the uncovered source lines\ndeno test --coverage=cov --coverage-threshold=80   # fails below the threshold\ndeno bench --filter <name>          # add `group` + `baseline: true` to Deno.bench for a comparison\n```\n\n`deno coverage` failing with `No covered files included in the report` means the tests never\nimported any local module — the report is empty, not broken.\n\n### Reading a package's API\n\n`deno doc` is the cheapest way to learn a surface, but three things trip agents up:\n\n- **It documents only the root export (`.`)**, not every subpath. `deno doc npm:zod` returned zero\n  `v3/` symbols even though `zod/v3` is a declared export. Name subpaths explicitly:\n  `deno doc jsr:@std/testing/mock`.\n- **If there is no root export it errors — and the error lists every subpath.**\n  `deno doc\n  jsr:@std/testing` fails with `Unknown export '.'` followed by\n  `./bdd ./mock ./snapshot ...`. That failure is the cheapest way to enumerate a package's\n  entrypoints.\n- **It is enormous.** `deno doc npm:zod` is 4,355 lines. Always `deno doc --filter <Symbol> <spec>`.\n\n`deno doc <dir>` documents every file in that directory (including `deno.json`, oddly).\n`deno doc --lint <file...>` requires explicit files — it will not infer them from an export map.\n\n### Dependencies, lockfile, and dependency age\n\n```bash\ndeno add npm:zod jsr:@std/path      # writes deno.json imports + deno.lock\ndeno install                        # install everything the config declares\ndeno outdated [--latest] [--update] # inventory; --update rewrites specifiers\ndeno why <pkg>                      # provenance\ndeno ci                             # frozen install from the lockfile, for CI\n```\n\n`--frozen` turns lockfile drift into a real failure with a diff:\n`error: The lockfile is out of date. Run 'deno install --frozen=false' ...`.\n\n_(2.9, unstable)_ **`--minimum-dependency-age` defaults to 24 hours.** A version published minutes\nago fails to resolve with\n`A newer matching version was found, but it was not used because it was\nnewer than the specified minimum dependency date`.\nAlias `--min-dep-age`; values are minutes (`120`), ISO-8601 durations (`P2D` — years are rejected),\nor a date (`2025-09-16`); `0` disables. The durable fix is `\"minimumDependencyAge\"` in `deno.json`,\nnot a flag on one command.\n\n**Two traps around that flag, both verified:**\n\n1. **`deno task` does not accept `deno run` flags.** `deno task --minimum-dependency-age=0 dev`\n   fails with `error: unexpected argument '--minimum-dependency-age' found`. `deno task` has its own\n   small flag set (`--cwd`, `--eval`, `--filter`, `--jobs`, `--if-present`, `--recursive`, `-c`).\n   Anything after the task **name** is appended to the task's command line, not parsed by Deno.\n   Options: put the flag in the task, use `deno task --eval \"deno run --min-dep-age=0\n   main.ts\"`,\n   or run the underlying `deno run` directly.\n2. **`deno x` does not pass it to the child.** `deno x` applies the flag while resolving/installing\n   the binary, then re-execs the tool as a _separate process_ whose argv is\n   `deno run --allow-all file:///…/deno_x_cache/npm-<tool>/…` — confirmed by `ps`. The flag is\n   absent, so anything the tool resolves at runtime falls back to the default 24-hour policy. Set\n   `minimumDependencyAge` in `deno.json` when a `deno x` tool needs a different policy.\n\n## Important rules\n\n- **Never conclude from an exit code you obtained through a pipe.** `cmd | tail` reports `tail`.\n- **`deno run` does not type-check.** \"It ran\" is not evidence about types. Only `deno check` is.\n- **`deno check <excluded-file>` exits 0 with a warning.** If output is\n  `Warning No matching files\n  found.`, you checked nothing — re-run with `--no-config`.\n- **Reach for `deno info` before reading source.** Nearly every \"framework bug\" that turns out to be\n  an import-map, version, or cache problem is visible in one `deno info` tree.\n- **Prefix `NO_COLOR=1`** on anything you will parse — Deno colours output even when redirected.\n- **Enable test sanitizers explicitly** _(2.9)_. Green tests do not mean no leaks.\n- **Do not run `deno clean` to test a stale-cache hypothesis.** Use `DENO_DIR=<tmpdir>` — it proves\n  the same thing and destroys nothing. Treat `deno clean` and unscoped `--reload` as needing\n  approval; prefer `--reload=<specifier>`.\n- **Grant the narrowest permission the error names**, never `-A`, when diagnosing.\n- **Add `--no-prompt`** in unattended runs so a permission gap fails instead of hanging.\n- Prefer `docs.deno.com` and `deno <cmd> --help` over recalled flags. Several 2.9 behaviours\n  (sanitizers off by default, the 24-hour dependency-age default) invert older documentation.\n\n### Verification notes\n\n- `deno lint --fix` is documented as fixing \"rules that support it\", but on 2.9.3 it modified no\n  file across four attempts (`prefer-const`, `no-unused-vars`, `eqeqeq`, `no-inferrable-types`) and\n  still exited 1. **Re-read the file after running it; do not assume it fixed anything.**\n- `deno test` flags `--repeats`, `--retry`, `--shard`, `--update-snapshots` were confirmed present\n  in `--help` but not exercised.\n- The `deno x` child-process finding was verified by inspecting the live process tree, not by\n  triggering a real age rejection inside a tool's runtime resolution.\n- All `deno check` / `deno info` / `deno test` / `deno doc` behaviours above were reproduced on a\n  scratch project. The claim that the **editor** checks only open files is standard LSP behaviour\n  and was _not_ re-verified here — the CLI half of the comparison was.\n",

  "help.md": "# help.md — when something is wrong and you do not know why\n\nA symptom-to-action playbook for the non-deterministic problems: things that hang, vanish, or\nsilently do nothing. **Reach for this before you start guessing**, and before you conclude the\nframework is broken.\n\nAspire-specific commands here were re-verified against **Aspire CLI 13.5.3**; see the receipt index\nin `aspire/SKILL.md`. Where a command does not exist, this file says so.\n\n> **The one rule this file exists to teach.** In the last round five agents lost hours to problems\n> the toolchain would have answered in seconds, because they hand-rolled `curl` probes instead of\n> asking the runtime. `aspire otel` — the command that shows logs, spans and traces — was run **zero\n> times** across all five. Ask the tools first.\n\n## Framework or package guidance is unavailable offline\n\nRun `netscript agent init --with-docs`. It installs a version-checked offline corpus and reports the\nlocal task-router entrypoint. The API portion is generated from the exact NetScript packages in the\nproject, including every published export subpath.\n\n---\n\n## `Healthy` is not proof\n\n`state: Running` + `healthStatus: Healthy` with an empty `healthReports` object means **nothing was\never checked** — health was inferred from the process being alive. A crash-looping resource under\nwatch mode, or one whose port never bound, reads as `Healthy`.\n\n```sh\naspire describe --format Json          # look at healthReports, not just healthStatus\naspire logs <resource> --tail 50       # what the process is actually doing\naspire otel logs <resource>            # structured logs from the telemetry API\n```\n\nIf `healthReports` is empty, you have no evidence. Get some before you believe the label.\n\n---\n\n## A dangling AppHost is causing conflicts\n\nPorts held, resources answering that are not yours, a stack that will not start cleanly.\n\n```sh\naspire ps --format Json --non-interactive --nologo           # inspect running AppHosts first\naspire describe --format Json --non-interactive --nologo     # inspect resource state\naspire resource <resource> stop                              # stop one resource when targeted cleanup is enough\naspire stop --apphost <exact-AppHost-path> --non-interactive --nologo\n```\n\n**Never kill `aspire agent mcp`** — those are your MCP servers, not AppHosts.\n\nOn a shared machine, confirm the thing answering a port is yours: compare the resource's _assigned_\nport from `aspire describe --format Json` against the fixed/default port you are probing. A foreign\nservice on a default port will happily answer and look healthy. If stopping the AppHost does not\nrestore a clean state, run `aspire doctor --format Json --non-interactive --nologo`; leave leftover\ncontainers for Aspire to reclaim rather than removing containers by hand.\n\nDo not use the host-wide `aspire stop` mode with `--all`. On shared hosts it can stop sibling runs,\nand it is not a reliable cleanup oracle: three independent agents saw it report\n`No running AppHost found` and exit 0 while processes rooted at the AppHost survived.\n\n## Vite will not start, or hangs\n\nDo not restart the whole stack.\n\n```sh\naspire resource <name> restart      # start | stop | restart\naspire logs <name> --follow         # watch it come back up\n```\n\n## An event does not fire — trigger, saga, worker, stream\n\nThis is where traces earn their keep. Do not add print statements.\n\n```sh\naspire otel traces <resource>    # follow the request across resources\naspire otel spans <resource>     # find the span that failed or never started\naspire otel logs <resource>      # structured logs, not console noise\naspire logs <resource> --search \"<term>\"   # full-text across log content\n```\n\nAlso available through the **Aspire MCP** tools (`list_traces`, `list_trace_structured_logs`,\n`list_structured_logs`, `list_console_logs`, `list_resources`) and the **NetScript MCP** server\n(`netscript agent mcp`), whose run model is a read model over the same OTel spans — `list_runs`,\n`get_run`, `get_recent_errors`. Use whichever is already connected.\n\n## You need the browser console\n\n**You almost certainly do not need Playwright for this.** Generated app resources emit\n`withBrowserLogs()` **by default**, so client-side failures — a `TypeError` thrown by an island, a\ndurable-stream consumer dying in the browser — land in the Aspire dashboard and in:\n\n```sh\naspire logs <app-resource>\naspire otel logs <app-resource>\n```\n\nThree agents last round fought Chrome and Playwright screenshot hangs to get information that was\nalready being collected for them.\n\n## You need real browser interaction\n\nUse Playwright for what it is actually for — clicking through a flow, asserting rendered state,\ncapturing screenshots — and **correlate what you see with `aspire logs` for the same moment.** The\nbrowser tells you what rendered; Aspire tells you why.\n\nOne trap that cost time: waiting on `networkidle` against a dev server with HMR **never settles**.\nWait on a DOM selector or a content condition instead.\n\n## The environment itself feels wrong\n\n```sh\naspire doctor --format Json     # diagnoses Aspire environment issues and verifies setup\n```\n\nThere is **no `netscript doctor`** command in `0.0.3`. If NetScript's own setup looks wrong, check\n`netscript --version` and `netscript config` instead.\n\n## A plugin install succeeded, but nothing is wired\n\nThe plugin's boundary never runs, a generated registry looks wrong, or install reported success but\nthe application behaves as though the plugin does not exist.\n\n```sh\nnetscript plugin doctor\n```\n\nRun this **before you read source or hand-probe endpoints**. It checks the plugin boundary and\ngenerated wiring from the same CLI surface that installed the plugin; an exit-zero install is not\nproof that the runtime registry is correct.\n\n## You are unsure how an API works\n\n**In this order:**\n\n1. **`deno doc jsr:@netscript/<pkg>/<subpath>`** — the exported surface, including every export\n   subpath. The helper you want is usually a few exports below the general-purpose one you already\n   found. Use `NO_COLOR=1` — `deno doc` emits ANSI escapes even when redirected, which corrupts\n   every grep.\n2. **The official NetScript docs**, through the connected NetScript MCP server when available.\n3. Only then, the source.\n\nGuessing an API signature and iterating against the type checker is slower than reading it once.\n\n## A command \"succeeded\" but nothing works\n\n**Verify the artefact, never the exit code.**\n\nA piped command reports the exit status of the _last stage in the pipe_ — `deno task check | tail`\nexits `0` while type checking fails. An `&&` chain short-circuiting on a no-op produces a false\nsuccess.\n\nDo not treat an exit-zero generator, plugin install, build or publish as proof. Check that the\nproduced files exist, type-check, and that the boundary actually runs.\n\n```sh\ndeno check <specific-file>   # not what your editor says\ndeno info <module>           # how it really resolved, and from which cache\ndeno task check              # read the output, not the exit code\n```\n\n## Types fail but nothing looks wrong\n\n```sh\ndeno info <module>    # resolution and cache — the most under-used diagnostic\ndeno check --reload   # rule out a stale cache\n```\n\nIf an import resolves somewhere unexpected, check for a `tsconfig.json` **above** your project:\ntools that walk upward will inherit it. A generated project should carry its own.\n\n---\n\n## Cleaning up after yourself\n\n```sh\naspire ps --format Json --non-interactive --nologo           # inspect before stopping anything\naspire describe --format Json --non-interactive --nologo     # inspect runtime/resource state\naspire resource <resource> stop                              # targeted stop when the whole stack should stay up\naspire stop --apphost <exact-AppHost-path> --non-interactive --nologo\n```\n\nRe-run `aspire ps` and `aspire describe` after stopping. Aspire's `dcp` helper processes can take\nabout 20 seconds to exit, so re-check rather than killing them. Leaving AppHosts running is how the\n_next_ run gets a port conflict it cannot explain; leftover containers are Aspire's to reclaim. If\ncleanup still looks wrong, use `aspire doctor --format Json --non-interactive --nologo` to diagnose\nthe container runtime, SDK, and certificates.\n\n`aspire cache clear` clears only the Aspire CLI's disk cache. It does **not** stop AppHosts or\nremove containers, so use it only for a CLI-cache problem—not as runtime cleanup.\n",

  "manifest.json": "{\n  \"name\": \"netscript-skills\",\n  \"version\": \"0.2.0\",\n  \"skills\": [\n    \"netscript\",\n    \"netscript-operate\",\n    \"netscript-build\",\n    \"netscript-design\",\n    \"aspire\",\n    \"deno\"\n  ],\n  \"files\": [\n    \"netscript/SKILL.md\",\n    \"netscript-operate/SKILL.md\",\n    \"netscript-build/SKILL.md\",\n    \"netscript-design/SKILL.md\",\n    \"netscript-design/references/GUIDELINES.md\",\n    \"aspire/SKILL.md\",\n    \"deno/SKILL.md\",\n    \"help.md\",\n    \"manifest.json\"\n  ]\n}\n",

  "netscript-build/SKILL.md": "---\nname: netscript-build\ndescription: 'Scaffold and build NetScript applications with the `netscript` CLI. USE FOR: init a project, contract-first flow, database lifecycle (init/generate/migrate/seed/status), add and sync plugins, add services, add UI pages and components, app chrome/navigation and theming, route renaming/moving/removal and router.ts reconciliation, generate registries. DO NOT USE FOR: monitoring, debugging, or performance analysis (use netscript-operate); Aspire orchestration (use the aspire skill).'\n---\n\n# NetScript Build\n\nChange the project with real `netscript` CLI verbs. Prefer the CLI for every mutation; discover the\ncurrent verb surface with the `list_commands` MCP tool if unsure.\n\n## Verb map\n\n| Task                       | Command                                           |\n| -------------------------- | ------------------------------------------------- |\n| Create a new project       | `netscript init`                                  |\n| Add a contract             | `netscript contract add`                          |\n| List contracts             | `netscript contract list`                         |\n| Generate from contracts    | `netscript generate runtime-schemas`              |\n| Generate plugin registries | `netscript generate plugins`                      |\n| Add a service              | `netscript service add`                           |\n| List services              | `netscript service list`                          |\n| Generate service wiring    | `netscript service generate`                      |\n| Add a plugin               | `netscript plugin install`                        |\n| Sync installed plugins     | `netscript plugin sync`                           |\n| Plugin diagnostics         | `netscript plugin doctor`                         |\n| List / inspect plugins     | `netscript plugin list` / `netscript plugin info` |\n| Initialize UI              | `netscript ui:init`                               |\n| Add a UI page/component    | `netscript ui:add`                                |\n| Remove a generated page    | `netscript ui:remove page <path>`                 |\n| Regenerate route modules   | `netscript generate routes`                       |\n\n## Database lifecycle\n\n| Step                          | Command                 |\n| ----------------------------- | ----------------------- |\n| Initialize database wiring    | `netscript db init`     |\n| Generate migrations/artifacts | `netscript db generate` |\n| Apply migrations              | `netscript db migrate`  |\n| Seed data                     | `netscript db seed`     |\n| Check status                  | `netscript db status`   |\n\nRun in order: `init → generate → migrate → seed`, then `status` to confirm.\n\n## Workflows\n\nBefore implementing an unfamiliar NetScript API or architecture, call MCP `find_guidance` with the\ntask. Follow its ordered section citations before choosing an API or architecture. Use `search_docs`\nfor literal lookup and `get_doc` for exact retrieval.\n\n## Installed diagnostic tools by symptom\n\nRun these from the initialized project root. The paths are installed by `netscript agent init`.\n\n| Symptom                                                            | First tool                                                                                                                    |\n| ------------------------------------------------------------------ | ----------------------------------------------------------------------------------------------------------------------------- |\n| Type errors, or `deno check` may have silently excluded the target | `deno run --allow-read --allow-run .llm/tools/run-deno-check.ts --root <path> --pretty`                                       |\n| Broad lint output hides the actionable files                       | `deno run --allow-read --allow-run .llm/tools/run-deno-lint.ts --root <path> --pretty`                                        |\n| A published API may have missing JSDoc or slow types               | `deno run --allow-read --allow-run .llm/tools/run-deno-doc-lint.ts --root <package> --pretty`                                 |\n| A generated Aspire scaffold may pin collision-prone host ports     | `deno run --allow-read .llm/tools/validation/check-aspire-host-ports.ts <project-root> --pretty`                              |\n| A change may violate focused code-quality rules                    | `deno run --allow-read .llm/tools/quality/scan-code-quality.ts --root <path> --pretty`                                        |\n| Dependencies may be behind stable registry releases                | `deno run --allow-read --allow-env --allow-net .llm/tools/deps/outdated.ts --pretty`                                          |\n| You do not know why a dependency is present                        | `deno run --allow-read --allow-run .llm/tools/deps/why.ts <package>`                                                          |\n| A generated project needs the complete CLI/plugin/DB/Aspire proof  | `deno run --allow-read --allow-write --allow-run --allow-net --allow-env .llm/tools/e2e/scaffold-e2e-test.ts --format pretty` |\n\nFor type-checking, prefer the installed `run-deno-check.ts`: bare `deno check` can print\n`No matching files found` and still exit 0 when configuration excludes the target. The runner\nreports its selected file count and fails when that count is zero.\n\n**You are offline or unfamiliar with a framework package/API.** Run\n`netscript agent init --with-docs`. The opt-in installs the release prose plus API documentation for\nevery export subpath of each exact NetScript package found in the project; the command reports the\nlocal starting point and fails instead of installing docs for a mismatched version.\n\n**Contract-first.** `netscript contract add` (define the schema/type contract) →\n`netscript generate runtime-schemas` (emit generated types) → implement against the generated\nsurface. Re-run `generate` after every contract change; do not hand-edit generated output.\n\n**Plugin lifecycle.** `netscript plugin install` → `netscript generate plugins` →\n`netscript plugin doctor`. `netscript generate plugins` is authoritative; the compatibility\n`plugin sync` command delegates to it.\n\n**A plugin install seemed to work, but its boundary never runs or the generated registry looks\nwrong.** Run `netscript plugin doctor` before reading source or hand-probing endpoints, then\nregenerate with `netscript generate plugins` only if the diagnostic identifies stale wiring.\n\n**Add a service.** `netscript service add` → `netscript service generate` to produce wiring.\n\n## Pages, chrome, navigation, and theme\n\nEvery page renders inside the app chrome in `routes/_layout.tsx`: the top bar, whose links are the\n`appNavigation` list in the app's `navigation.ts`. Do not build a per-page header or nav.\n\n- `netscript ui:add page <path>` links one-segment pages in the top bar automatically. Pass\n  `--nav <label>` to link a nested page or set the label, and `--no-nav` for pages that should not\n  be linked. Its `Next:` lines name the files that own the frame.\n- A page that needs its own full-screen frame (a sign-in screen) opts out by adding its prefix to\n  `chromelessRoutePrefixes` in `navigation.ts`; `/design` is the scaffold's example.\n- Start each page from `<main class='ns-shell ns-section ns-stack ns-stack--lg'>` plus `PageHeader`,\n  which `ui:add page` writes, and compose the app-owned primitives from `@app/components/ui/mod.ts`.\n  Browse the running app's `/design` routes for the component gallery and tokens.\n- There is one app-wide theme. `assets/theme-preset.json` names the preset (Studio Utility for new\n  apps), and `routes/_app.tsx` stamps it on `<html>` as `data-theme`, `data-flavor`, `data-density`,\n  and `data-scheme` (light or dark, flipped by `ThemeToggle`). `assets/tokens.css` holds the\n  preset's generated `--ns-*` tokens, which `client.ts` loads on every route, and\n  `assets/theme-bridge.css` exposes them as Tailwind `*-ns-*` utilities.\n- Switch the preset with `netscript ui:apply --preset <id>`. Fine-tune it by aliasing semantic roles\n  in `tokens/semantic.tokens.json`: create the file, and when `tokens.config.json` exists\n  (`ui:apply` writes it) add `\"override\": \"tokens/semantic.tokens.json\"` to it, because\n  `tokens build` ignores an override the config does not name. Then run `netscript tokens build`. Do\n  not run `tokens init` after `ui:apply`: it fails without `--force`, which resets the override file\n  and replaces `tokens/source/`. Never hand-edit the generated `tokens.css`, `theme-bridge.css`,\n  `tokens.json`, `fonts.json`, or `theme-preset.json`. Never scope theme variables to one page's\n  wrapper; there is no per-page theme.\n\nRead `web-layer/how-to/theme-your-app` through MCP `get_doc` before changing the theme or the frame,\nand `web-layer/how-to/customize-fresh-ui` before editing routes, islands, or registry components. An\napp without `navigation.ts` was scaffolded before shared navigation: its `routes/_layout.tsx` shows\nthe top bar only for an allowlist of routes, so add new pages there.\n\n## Route lifecycle: rename, move, or remove a page\n\nFor route renaming or moving, read `web-layer/route` (\"Renaming or Moving a Route\") and\n`web-layer/generated-surface` through MCP `get_doc` before editing. `ui:add page` writes an editable\npage, a string-literal registration in `router.ts`, and (for linked pages) an `appNavigation` entry;\nit does not bind through the filesystem-generated `routes` tree. Moving a directory can leave a\nstale URL while type checking passes.\n\nFollow the checklist: move the page with its owned loader/island and sidecar, repair imports,\nreconcile the `appRoutes` pattern/key/id, the page binding and its `navigation.ts` entry, update\nconsumers, run `netscript generate routes` to refresh `.generated/manifest.ts` and\n`.generated/routes.ts` without a Vite build, then type-check and verify navigation, new/old URLs,\nand loader/island behavior.\n\nTo remove a page that `ui:add page` generated and you have not edited, run\n`netscript ui:remove page <path>` (preview with `--dry-run`). It deletes the page triad, its\n`router.ts` registration and its `navigation.ts` link, then refreshes the derived route modules; it\nrefuses edited files, so prune an edited page, its registration, link, and consumers by hand,\npreserving shared modules still in use. `netscript ui:remove <name>` handles copied Fresh UI\nregistry items. There is no route rename verb: do not guess one, and never hand-edit\n`.generated/manifest.ts` or `.generated/routes.ts`.\n\n## Safety rules\n\n- Never hand-edit generated registries or generated types — re-run the generator instead.\n- Do not delete lock files or caches.\n- Run generators after any contract, plugin, or service change so the generated surface stays in\n  sync.\n\n## Boundaries\n\n- Observing the app (health, failing runs, performance) lives in `netscript-operate`.\n- Aspire start/stop and the resource graph live in the `aspire` skill.\n",

  "netscript-design/SKILL.md": "---\nname: netscript-design\ndescription: 'Choose a Fresh UI theme and build or customize NetScript UI with its design language, token compatibility contract, quality method and self-audit. Use for visual design, theme selection and on-theme components; not backend architecture or generic Deno tooling.'\n---\n\n<!-- Generated from canonical GUIDELINES.md; source SHA-256: 3c9b6292547f979addaaef7ece3b365fbf96661a85e921b863d0c926b43abc15.\nRelease links are filled in from the invoking CLI version during agent init. -->\n\n# NetScript design\n\n## Theme an app today\n\nNew Fresh apps start on **Studio Utility** (`studio-utility`): ink on neutral gray,\nsharp corners, hairline rules and compact density. Preserve an app's chosen preset unless the\nuser asks to change it. Read Theme your app (MCP/local-doc slug: `web-layer/how-to/theme-your-app`)\nfor release-matched commands and app wiring; [released source](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/site/web-layer/how-to/theme-your-app.md).\n\nSwitch the whole app with `netscript ui:apply --preset <preset-id>`, for example\n`netscript ui:apply --preset studio-cloud`. In a workspace, add `--app <name>`.\nThe command records the preset in `tokens.config.json`, rebuilds generated assets, keeps\nthe semantic override file and installs the registry-owned DESIGN.md/SKILL.md pair under\n`.agents/skills/fresh-ui-theme-<preset-id>/` relative to the Fresh app. Read that pair first.\nIn a scaffolded workspace, select `apps/<app>/` (the app selected by `--app`) before resolving\nthese paths. The shared skill can live at the workspace root while the theme pair lives inside\nthe app. In a standalone Fresh app, resolve them from its root. Do not resolve app paths relative\nto this SKILL.md.\nUse `netscript init my-app --preset <preset-id>` to choose a preset at scaffold time.\n`ui:add theme-<preset-id>` alone does not select the app's token preset.\n\nThe current tokens v2 IDs and document links below come from the theme registry. A design\nlanguage name such as `studio` is not a preset ID; use `studio-utility` or another\nlisted Studio flavor. `ns-one` preserves the earlier default.\n\n| Preset ID | Installed pair (paths relative to the selected Fresh app) | Published source pair |\n| --- | --- | --- |\n| ns-one | `.agents/skills/fresh-ui-theme-ns-one/DESIGN.md` · `.agents/skills/fresh-ui-theme-ns-one/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-utility | `.agents/skills/fresh-ui-theme-studio-utility/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-utility/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-cloud | `.agents/skills/fresh-ui-theme-studio-cloud/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-cloud/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-workshop | `.agents/skills/fresh-ui-theme-studio-workshop/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-workshop/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-playful | `.agents/skills/fresh-ui-theme-studio-playful/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-playful/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-ledger | `.agents/skills/fresh-ui-theme-studio-ledger/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-ledger/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-atelier | `.agents/skills/fresh-ui-theme-studio-atelier/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-atelier/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| studio-signal | `.agents/skills/fresh-ui-theme-studio-signal/DESIGN.md` · `.agents/skills/fresh-ui-theme-studio-signal/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| tonal | `.agents/skills/fresh-ui-theme-tonal/DESIGN.md` · `.agents/skills/fresh-ui-theme-tonal/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tonal/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tonal/SKILL.md) |\n| bloom | `.agents/skills/fresh-ui-theme-bloom/DESIGN.md` · `.agents/skills/fresh-ui-theme-bloom/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/bloom/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/bloom/SKILL.md) |\n| cupertino | `.agents/skills/fresh-ui-theme-cupertino/DESIGN.md` · `.agents/skills/fresh-ui-theme-cupertino/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/cupertino/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/cupertino/SKILL.md) |\n| liquid | `.agents/skills/fresh-ui-theme-liquid/DESIGN.md` · `.agents/skills/fresh-ui-theme-liquid/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/liquid/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/liquid/SKILL.md) |\n| fluent | `.agents/skills/fresh-ui-theme-fluent/DESIGN.md` · `.agents/skills/fresh-ui-theme-fluent/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/fluent/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/fluent/SKILL.md) |\n| brutal | `.agents/skills/fresh-ui-theme-brutal/DESIGN.md` · `.agents/skills/fresh-ui-theme-brutal/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/brutal/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/brutal/SKILL.md) |\n| filigrane | `.agents/skills/fresh-ui-theme-filigrane/DESIGN.md` · `.agents/skills/fresh-ui-theme-filigrane/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/filigrane/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/filigrane/SKILL.md) |\n| terminal | `.agents/skills/fresh-ui-theme-terminal/DESIGN.md` · `.agents/skills/fresh-ui-theme-terminal/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/terminal/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/terminal/SKILL.md) |\n| pixel | `.agents/skills/fresh-ui-theme-pixel/DESIGN.md` · `.agents/skills/fresh-ui-theme-pixel/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/pixel/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/pixel/SKILL.md) |\n| tactile | `.agents/skills/fresh-ui-theme-tactile/DESIGN.md` · `.agents/skills/fresh-ui-theme-tactile/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tactile/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tactile/SKILL.md) |\n| ledger | `.agents/skills/fresh-ui-theme-ledger/DESIGN.md` · `.agents/skills/fresh-ui-theme-ledger/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/ledger/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/ledger/SKILL.md) |\n| signal | `.agents/skills/fresh-ui-theme-signal/DESIGN.md` · `.agents/skills/fresh-ui-theme-signal/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/signal/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/signal/SKILL.md) |\n| glass | `.agents/skills/fresh-ui-theme-glass/DESIGN.md` · `.agents/skills/fresh-ui-theme-glass/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/glass/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/glass/SKILL.md) |\n| macos-27 | `.agents/skills/fresh-ui-theme-macos-27/DESIGN.md` · `.agents/skills/fresh-ui-theme-macos-27/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/macos-27/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/macos-27/SKILL.md) |\n| apple-classic | `.agents/skills/fresh-ui-theme-apple-classic/DESIGN.md` · `.agents/skills/fresh-ui-theme-apple-classic/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/apple-classic/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/apple-classic/SKILL.md) |\n| fluent-2-web | `.agents/skills/fresh-ui-theme-fluent-2-web/DESIGN.md` · `.agents/skills/fresh-ui-theme-fluent-2-web/SKILL.md` | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/fluent-2-web/DESIGN.md) · [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/token-presets/fluent-2-web/SKILL.md) |\n\n## Shared design rules\n\nUse the [bundled canonical guidelines](references/GUIDELINES.md) for the shared rules. They are a\nlocal snapshot of the design-system source. Their provisional/planned implementation notes\ndescribe the original design plan; use Theme your app and the installed pair for current tokens\nv2 behavior and CLI availability.\n\n- **Choose a theme:** read §6 (theme catalogue) and §2.4 (preset design constraints), then the chosen\n  theme's pair. Follow the user's goal and the current preset IDs above;\n  the catalogue distinguishes faithful, inspired and own languages.\n- **Build compatible UI:** read §1 (ownership), §2 (theme architecture) and §3 (compatibility\n  contract), plus the chosen DESIGN.md and SKILL.md. Use semantic/component tokens and check\n  light and dark schemes. Discover CLI/API operations through the installed NetScript tooling.\n- **Check the result:** follow §4 (quality method), especially §4.5 (self-audit), and §5\n  (anti-patterns). The chosen theme pair supplies the concrete visual rules and state coverage.\n- **Create a theme:** follow §7 and the planned shipping boundary in §8; do not improvise a\n  competing token contract.\n\n## Theme specifications and procedures\n\n`ui:apply` installs each preset's pair through its registry theme item. The local pair is the\nsource of truth for that app; this shared skill links to it without duplicating its contents.\nWhen the pair is not installed, use the published preset links above. The 11 complete\ndesign-language specifications are also listed below. Read the Design system gallery with\nMCP/local-doc slug `design-system`; its [released specifications](https://github.com/rickylabs/netscript/tree/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/)\nare pinned to the same release as these source links.\n\n| Theme | Specification | Agent procedure |\n| --- | --- | --- |\n| studio | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/studio/SKILL.md) |\n| tonal | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tonal/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tonal/SKILL.md) |\n| bloom | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/bloom/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/bloom/SKILL.md) |\n| cupertino | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/cupertino/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/cupertino/SKILL.md) |\n| liquid | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/liquid/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/liquid/SKILL.md) |\n| fluent | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/fluent/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/fluent/SKILL.md) |\n| brutal | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/brutal/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/brutal/SKILL.md) |\n| filigrane | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/filigrane/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/filigrane/SKILL.md) |\n| terminal | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/terminal/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/terminal/SKILL.md) |\n| pixel | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/pixel/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/pixel/SKILL.md) |\n| tactile | [DESIGN.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tactile/DESIGN.md) | [SKILL.md](https://raw.githubusercontent.com/rickylabs/netscript/{{NETSCRIPT_RELEASE_REF}}/docs/design-system/themes/tactile/SKILL.md) |\n",

  "netscript-design/references/GUIDELINES.md": "# NetScript Custom Design Guidelines\n\nHow to design a Fresh UI theme that matches the quality of the reference themes and works\nwith the NetScript framework.\n\nThe guidelines have two readers:\n\n- a designer creating or extending a theme;\n- an AI agent working from a `SKILL.md` and `DESIGN.md` pair.\n\nThe guidelines define the token contract every theme follows (§1 to §3), the method for designing\nand checking a theme (§4 and §5), the existing themes (§6), and the steps for adding and shipping a\nnew one (§7 and §8).\n\n> **Status: token names are provisional.** The role names below are the current Figma contract. The\n> tokens build (#2414) turns them into DTCG 2025.10 tokens with resolver modes. The component\n> anatomy spec (#2416) freezes anatomy and data-attribute variants. Until both land, treat names as\n> stable and values as owned by Figma. Do not invent new core role names.\n\n## 1. Two rules that override everything\n\n1. **Figma owns values; code owns names.** A theme changes the values of existing roles, tiers and\n   modes. It never renames a core role or introduces a new core role on its own. New namespaced\n   roles come only through a style's role manifest (§2.4). CI rejects exported token names that code\n   does not know.\n2. **A theme is a language, not a palette.** Recolouring and re-rounding the default UI is not a\n   theme. A theme language is a **style**: it owns a depth model, a shape language, a type system\n   and its own version of every component, each traceable to a documented reference (§2.4).\n\n## 2. Theme architecture\n\nFigma and code describe the same system. Figma stores values in variable collections and modes. In\ncode, the tokens build (#2414) stores tokens in three DTCG 2025.10 tiers and selects between\ncontexts with a DTCG resolver file. This section maps one onto the other. Ownership follows the epic\n(#2412, decision 2): Figma owns values; code owns names, tiers, modes and component anatomy.\n\n### 2.1 Three token tiers\n\n| Tier          | What it holds                                                                                                                                                                                                                                                                                   | Figma source                                                                                                                                                                       | Code surface (provisional until #2414)                            | Who may read it                                          |\n| ------------- | ----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- | ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- | ----------------------------------------------------------------- | -------------------------------------------------------- |\n| **Primitive** | Raw values only: colour ramps (oklch with a hex fallback), dimensions, durations, font families. Radix 12-step ramps (gray, slate, sand, mauve, blue, violet, orange, indigo, tomato, lime, grass, amber, red, teal) and theme ramps (`ember`, `band`, `paper`, `glass`, `shadow`, `swiss-red`) | `Primitives` collection (Value mode)                                                                                                                                               | Internal custom properties, e.g. `--ns-band-*`                    | The semantic tier only. Components never read primitives |\n| **Semantic**  | **Aliases only.** Every value references a primitive (or another semantic role), never a raw hex, px or ms. Core roles plus each style's namespaced roles (§2.4)                                                                                                                                | `Scheme` collection (Light, Dark). Its aliases are selected through the `Theme set` (`Theme` or `Theme B`), `Base gray`, `Base accent`, `Density` and `Studio flavor` modes (§2.2) | `--ns-*` (core) and `--ns-<theme>-*` (styles)                     | Component tokens and L2 component CSS                    |\n| **Component** | Part and state tokens (`button.*`, `input.*`, `card.*`, …) that alias semantic roles, so heavy customization is a token edit, not a CSS override                                                                                                                                                | Variable bindings on library components; there is no component collection yet                                                                                                      | Named by the tokens build from the component anatomy spec (#2416) | That component's own CSS only                            |\n\n- **Derived values.** Tints, hovers and other mixes are not raw values in the semantic tier.\n  `$extensions.netscript.derive` describes them. CSS keeps `color-mix()`, and Figma receives the\n  computed value.\n- **Collections and modes are not tiers.** `Scheme`, `Theme`, `Theme B`, `Base gray`, `Base accent`,\n  `Density` and `Studio flavor` modes are contexts the resolver chooses between (§2.2). `Theme set`\n  only switches the aliases between `Theme` and `Theme B`. None of them adds a fourth tier.\n- **Raw values inside Figma modes.** Some Theme modes still store raw values in slots that are\n  semantically aliases, for example Tactile's `surface/{l,d}/*` and Fluent's `accent/{l,d}/solid`.\n  Each theme's `DESIGN.md` records them. Before export, the tokens build (#2414) splits each one\n  into a primitive and an alias.\n- **Node-level exceptions are Figma-only.** A primitive or raw value bound directly on a Figma node\n  is a temporary exception. The theme's `DESIGN.md` names the role that replaces it, pending in\n  #2414. It never ships in L2 component CSS.\n- **Layer ownership is unchanged.** L0/L1 own platform behaviour, attributes and prop getters. L2\n  registry components consume component and semantic tokens. An L2 component never imports another\n  L2 component.\n\n### 2.2 How Figma collections map to the resolver\n\n| Figma collection (modes)                                                                  | What it selects                                                                                 | Token resolver (#2414)                                                                                                                        | Root attribute (provisional) |\n| ----------------------------------------------------------------------------------------- | ----------------------------------------------------------------------------------------------- | --------------------------------------------------------------------------------------------------------------------------------------------- | ---------------------------- |\n| `Scheme` (Light, Dark)                                                                    | The semantic role values for each scheme                                                        | `scheme` modifier: `light`, `dark`                                                                                                            | `data-scheme`                |\n| `Theme` (Studio, Ledger, Filigrane, Signal, Tonal, Glass, Brutal, Fluent, Tactile, Pixel) | Language values: fonts, type scale, radii, materials, shadow recipe, ring                       | `theme` modifier, with one context per **language preset** (§2.3), not one per Figma mode                                                     | `data-theme`                 |\n| `Theme B` (Bloom, Cupertino, Liquid, Terminal, macOS 27, Apple Classic, Fluent 2 Web)     | Language values, as for `Theme`                                                                 | The same `theme` modifier                                                                                                                     | `data-theme`                 |\n| `Theme set` (A, B)                                                                        | Which Theme collection the semantic roles alias through: A selects `Theme`, B selects `Theme B` | Not a modifier; the `theme` modifier covers both Theme collections                                                                            | —                            |\n| `Density` (Comfortable, Compact, Dense, Airy, Chunky)                                     | Control, page, section, card, table and badge spacing                                           | `density` modifier. The token resolver specifies `comfortable` and `compact` only; `dense`, `airy` and `chunky` need a resolver schema change | `data-density`               |\n| `Studio flavor` (Utility, Cloud, Workshop, Playful, Ledger, Atelier, Signal)              | Personality on top of the Studio language                                                       | Not a modifier. Each flavor expands into a Studio preset                                                                                      | `data-flavor` (Studio only)  |\n| `Base gray` (Neutral, Slate, Sand, Mauve)                                                 | Which gray ramp a theme sits on                                                                 | Not a modifier. A preset parameter                                                                                                            | `data-gray`                  |\n| `Base accent` (Ink, Blue, Violet, Orange, Indigo, Tomato, Lime)                           | Which accent ramp drives `primary/*`                                                            | Not a modifier. A preset parameter                                                                                                            | `data-accent`                |\n| `Primitives` (Value)                                                                      | Raw ramps                                                                                       | The primitive tier; no modifier                                                                                                               | —                            |\n\nThis Figma plan allows **10 modes per collection**, and `Theme` uses all 10. A second collection,\n`Theme B`, holds the modes for Bloom, Cupertino, Liquid and Terminal, and for the planned macOS 27,\nApple Classic and Fluent 2 Web themes (#2443). The semantic roles alias through the `Theme set`\ncollection: set A selects `Theme` and set B selects `Theme B`. Each language has its own mode.\n\nThe `Theme B` modes were seeded with copies of existing values: Bloom from Tonal; Cupertino, Liquid,\nmacOS 27 and Apple Classic from Glass; Terminal from Signal; and Fluent 2 Web from Fluent. Each mode\ncan diverge. Until a language's own values are set, its mode resolves to its seed values, which are\nprototype evidence only. Before a language ships, its values must come from its own mode, and the\ntoken export (#2414) must give each language preset its own complete core-role map. When both\ncollections are full, a new language replaces a mode or needs a new Theme collection. The token\nresolver (#2414) has no mode limit in code.\n\n### 2.3 Supported resolver axes\n\nThe axes are scheme × theme × flavor × density × gray × accent. **Not every permutation exists.**\nThe unit of support is the **language preset**: a fixed choice of Theme values, density, gray and\naccent (and, for Studio, flavor), designed and reviewed in both schemes.\n\n| Axis      | Values                                                                                                             | Where it applies                                   | Supported today                                                                                                      |\n| --------- | ------------------------------------------------------------------------------------------------------------------ | -------------------------------------------------- | -------------------------------------------------------------------------------------------------------------------- |\n| `scheme`  | light, dark                                                                                                        | Every preset                                       | Both schemes for every preset; each dark is designed, not inverted                                                   |\n| `theme`   | `studio`, `tonal`, `bloom`, `cupertino`, `liquid`, `fluent`, `brutal`, `filigrane`, `terminal`, `pixel`, `tactile` | —                                                  | One preset per language; Studio has seven, one per flavor                                                            |\n| `flavor`  | utility, cloud, workshop, playful, ledger, atelier, signal                                                         | Studio only                                        | Each flavor fixes its own gray, accent and density (Studio `DESIGN.md` → _Flavors_). Every other language ignores it |\n| `density` | comfortable, compact (token resolver); dense, airy, chunky (Figma only)                                            | Studio flavors; a few languages set one explicitly | Fixed per preset; not a free user override yet                                                                       |\n| `gray`    | neutral, slate, sand, mauve                                                                                        | Studio flavors                                     | Fixed per preset. The other languages alias their own ramps inside their Theme mode and ignore it                    |\n| `accent`  | ink, blue, violet, orange, indigo, tomato, lime                                                                    | Studio flavors                                     | Fixed per preset, as for gray                                                                                        |\n\n**Precedence.** The resolver applies `theme` (with `flavor` for Studio) as a preset that fixes\ndensity, gray and accent. `scheme` then selects the Light or Dark values. An app's override layer\n(#2414) applies last, on the semantic tier only. A preset ignores attempts to change an axis it\nfixes, and the builder (§8) offers only supported combinations. A free axis, such as any density on\nany language, needs a resolver schema change (#2414) and a contrast run for every new permutation.\n\n**Fixed axes per language.** This table comes from each theme's `DESIGN.md` → _NetScript Mapping_.\nThe mode assignments are read from the Figma library and are not yet verified in code (#2414). Modes\nin set B live in `Theme B` and still hold their seed values (§2.2).\n\n| Language  | Figma Theme mode                         | Density                                   | Gray × accent                                           |\n| --------- | ---------------------------------------- | ----------------------------------------- | ------------------------------------------------------- |\n| Studio    | `Studio`                                 | per flavor (Utility: compact)             | per flavor (Utility: neutral × ink)                     |\n| Tonal     | `Tonal`                                  | comfortable; M3 component sizes are fixed | mauve × violet, inside the mode                         |\n| Bloom     | `Bloom` (set B, seeded from `Tonal`)     | none (literal geometry)                   | none; Bloom reads `bloom/*`                             |\n| Cupertino | `Cupertino` (set B, seeded from `Glass`) | comfortable                               | slate × blue, inside the mode                           |\n| Liquid    | `Liquid` (set B, seeded from `Glass`)    | comfortable                               | slate × blue, inside the mode; own values in `liquid/*` |\n| Fluent    | `Fluent`                                 | none (WinUI defaults)                     | neutral gray × WinUI accent, inside the mode            |\n| Brutal    | `Brutal`                                 | none (comfortable default)                | sand × amber, inside the mode                           |\n| Filigrane | `Filigrane`                              | none                                      | sand × tomato, inside the mode                          |\n| Terminal  | `Terminal` (set B, seeded from `Signal`) | compact                                   | gray × lime, inside the mode                            |\n| Pixel     | `Pixel`                                  | comfortable                               | sand-family × amber, inside the mode                    |\n| Tactile   | `Tactile`                                | none                                      | none; Tactile reads `tactile/*`                         |\n\n**Migration from today's selectors.** Code today (NS One) scopes light on `:root` and dark on\n`[data-theme='dark']`. The new model moves the scheme to `data-scheme` and gives `data-theme` to the\nlanguage: `data-theme=\"dark\"` becomes `data-theme=\"<language>\" data-scheme=\"dark\"`. Acceptance for\nthe tokens build (#2414) requires that existing `--ns-*` names keep resolving or have a documented\nmigration, and that NS One renders unchanged. The tokens build therefore either keeps\n`[data-theme='dark']` resolving as the default preset's dark scheme or ships that migration, with a\n`ui:migrate` step for app-owned copies. Never rename an existing `--ns-*` name without a migration.\n\n### 2.4 Styles and token-only presets\n\nThere are two kinds of theme. Keep them apart.\n\n- **Token-only preset.** Assigns values to existing roles: a Studio flavor, a gray or accent choice,\n  an app's brand theme. It adds no names and no component sources. Most app themes are this kind.\n- **Style.** Every theme language (Studio, Tonal, Bloom, Cupertino, Liquid, Fluent, Brutal,\n  Filigrane, Terminal, Pixel, Tactile) is a style, in the sense shadcn uses the word: it restyles\n  **every** component, including shape, borders, fills, shadows, decorations and inner markup, over\n  one shared contract. A Pixel switch is Pixel's own switch, not the base switch with a smaller\n  radius.\n  - **The contract does not change between styles** (#2416): each component keeps its props,\n    `data-part` names, `data-variant`, `data-size` and `data-state` values, slots, APG pattern and\n    keyboard map. The contract tests run against every style.\n  - **Tokens stay separate axes** under every style: scheme, gray, accent, radius and density.\n  - A style declares:\n    1. **Its component sources:** one per component, shipped as a registry `style` item (#2415).\n    2. **A role manifest:** every namespaced role it adds, as `<theme>/<path>` →\n       `--ns-<theme>-<path>`, each with a Light and a Dark alias. Until the tokens build has a\n       machine-readable manifest, the list is the _Language roles_ row in the theme's `DESIGN.md` →\n       _NetScript Mapping_. The tokens build registers every listed role before the style ships;\n       unknown names fail CI.\n    3. **A complete core map:** every core semantic role still resolves under the style, so\n       token-only presets and app-owned components keep working.\n  - A style restyles its own components only, never app-owned markup outside them.\n- **In Figma,** each style is a set of component sets named `<Style>/<Component>`, with the same\n  property names, values and layer names as the base set, so an instance swap keeps every override.\n  Variables carry the token axes; variants carry states and sizes inside a style.\n\nStyles with namespaced roles today: `studio/*`, `liquid/*`, `tactile/*`, `bloom/*`, `cupertino/*`,\n`fluent/*` and `pixel/*`. Only that style's components read its namespaced roles. A Studio flavor is\na token-only preset inside the Studio style.\n\n### 2.5 Core semantic roles (every theme defines all of them, in Light and Dark)\n\nThe CSS custom property comes from each variable's code syntax. For example, `surface/bg` maps to\n`var(--ns-bg)` and `surface/card` to `var(--ns-card)`.\n\n- **Surfaces:** `surface/bg`, `surface/surface`, `surface/card`, `surface/raised`, `surface/muted`,\n  `surface/hover`, `surface/selected`, `surface/overlay`, `surface/container`,\n  `surface/container-high`, `surface/container-highest`, `surface/inverse`.\n- **Text:** `text/fg`, `text/card`, `text/muted`, `text/subtle`, `text/inverse`, `ink/fg`.\n- **Borders:** `border/default`, `border/subtle`, `border/hover`, `border/strong`, `border/input`,\n  `border/ring`, `border/ink`, `border/control`.\n- **Intents** (each has `default`, `hover`, `fg`, `subtle`, `border`, `text`): `primary`, `accent`,\n  `secondary`, `success`, `warning`, `destructive`, `info`. Primary also has `primary/container` and\n  `primary/on-container`.\n- **Actions and state:** `action/primary-bg`, `action/primary-fg`, `action/primary-border`,\n  `state/disabled-container`, `state/disabled-fg`.\n- **Depth:**\n  - `elevation/ambient`, `elevation/key`, `effect/shadow`;\n  - `bevel/{highlight,lip,edge,inset,solid-highlight,solid-lip,glow}`;\n  - `material/{fill,fill-strong,stroke,track}`.\n- **Language accents** (only meaningful in their theme, but always defined): `aurora/{1..4}`,\n  `block/{yellow,blue,green,pink,purple,ink-text}`, `frame/ink`, `control/ink`.\n\n### 2.6 Variants and states are data attributes\n\nModes, variants and states are data attributes (`data-variant`, `data-size` and `data-state`), not\nBEM modifier classes (epic Decision 4).\n\nA style restyles every variant and may change a component's inner markup. It never changes the\ncontract: the same props, parts and `data-*` values exist in every style (#2416). A style that needs\na new variant value, such as Studio's card variants or Bloom's notched widget, adds it to the\ncomponent spec first, so every style can render it.\n\n## 3. Compatibility contract (MUST)\n\n1. **Semantic roles only in components.** Components read their component tokens and semantic roles,\n   never primitives. The only exception is a Figma node-level correction (§2.1). It is recorded in\n   the theme's `DESIGN.md`, removed when the tokens build (#2414) adds the role, and never ships in\n   L2 component CSS.\n2. **Both schemes are complete.** Every core role has a designed Light and a designed Dark value.\n3. **Shippable effects only.** Every visual effect needs a web implementation. Some implementations\n   only approximate the Figma effect:\n\n   | Figma effect           | Web implementation / approximation                                                                                                      |\n   | ---------------------- | --------------------------------------------------------------------------------------------------------------------------------------- |\n   | `GLASS`                | Approximation: `backdrop-filter` blur plus layered borders and gradients. CSS has no refraction or lensing, so never call it equivalent |\n   | Drop and inner shadows | `box-shadow`                                                                                                                            |\n   | Gradient strokes       | `border-image` or a mask                                                                                                                |\n   | Bevels and lips        | stacked shadows or pseudo-elements                                                                                                      |\n\n   Every translucent material needs an opaque fallback (`@supports not (backdrop-filter: …)`,\n   `prefers-reduced-transparency`, `prefers-contrast: more`). Glass, the preference modes and\n   scroll-dependent effects (scroll edges, sticky glass bars) also need visual proof from the visual\n   regression tests (#2419): a Playwright screenshot compared with the Figma render. Anything that\n   cannot be shipped is not part of the theme.\n4. **Web Platform base.** Use native `<dialog>`, the Popover API, CSS anchor positioning and our\n   Preact behaviour. Never use a React-only library (epic Decision 3).\n5. **Licensable assets only.**\n   - **Fonts:** Google Fonts, other OFL fonts, or system stacks. SF Pro and Segoe UI cannot be\n     embedded; ship them only as system-stack fallbacks. SF Pro is listed in Figma but renders blank\n     from the Plugin API.\n   - **Icons:** Lucide (ISC), Fluent System Icons (MIT), or our own pixel set. No trademarked\n     product logos (Microsoft 365, Apple, Mojang).\n   - **Reference brands:** Polaris, Mistral and Minecraft Ore UI inform patterns. Never copy their\n     colours, marks or assets.\n6. **Accessibility is part of the theme.** Every theme ships with:\n   - text at WCAG 2.2 AA (4.5:1 normal, 3:1 large);\n   - non-text contrast of 3:1 for input, checkbox, radio and switch boundaries, and for focus\n     indicators;\n   - a visible focus indicator of at least 2px;\n   - states that never rely on shadow or colour alone;\n   - reduced-motion and RTL mirroring;\n   - hit targets of at least 24px (44px recommended for touch).\n\n## 4. The quality method\n\nFollow these steps for every language, from first draft to design sign-off.\n\n### 4.1 Anchor in a documented system: measure it, don't guess\n\nEach language has a public or open-source primary reference. Measure that source directly; don't\nwork from memory.\n\n| Language  | Anchor                                                                                                                                                                                        |\n| --------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Studio    | shadcn/ui 2026 styles and Linear, with Geist and AlignUI                                                                                                                                      |\n| Tonal     | Material 3 Expressive                                                                                                                                                                         |\n| Bloom     | Material You, widget-first                                                                                                                                                                    |\n| Cupertino | Apple-inspired classic: grouped-list and typography cues from Apple's pre-Liquid platforms, in a hand-built composition (not strict macOS 15 / iOS 18 fidelity)                               |\n| Liquid    | Apple macOS 27 / iOS 27 Liquid Glass (official Figma kits)                                                                                                                                    |\n| Fluent    | WinUI theme resources and Fluent 2 (MIT)                                                                                                                                                      |\n| Brutal    | Gumroad UI and neobrutalism.dev                                                                                                                                                               |\n| Filigrane | NetScript-defined minimal typography; FT Origami o3 and Guardian Source for focus, data and accent patterns, without newspaper chrome                                                         |\n| Terminal  | Charm Lip Gloss and Bubbles                                                                                                                                                                   |\n| Pixel     | the Mistral pixel idea, plus Ore UI component cues                                                                                                                                            |\n| Tactile   | Themesberg Neumorphism UI and flutter_neumorphic (verified upstream, pinned), plus setproduct guidance adopted as local parameters (upstream unverified; see Tactile `DESIGN.md` → _Sources_) |\n\nOfficial kits are available as Figma community libraries; Liquid's values are measured from the\nmacOS 27 and iOS 27 kits. Open-source theme resources give exact values.\n\n### 4.2 Write the thesis before drawing\n\nWrite one sentence and three signature moves that nobody would mistake for another theme. Two\nexamples:\n\n- **Bloom:** notch-cut pastel widgets, a large regular grotesk and black action discs.\n- **Tactile:** one material and one light. Convex keys, concave wells, and selected means sunk.\n\n### 4.3 Vary every axis, not only colour\n\nA theme is unique only when most of these axes differ from its neighbours:\n\n| Axis               | Questions to answer                                                                                                                           |\n| ------------------ | --------------------------------------------------------------------------------------------------------------------------------------------- |\n| Depth model        | Flat, hairline, elevated, glass, bevel/lip, neumorphic, offset-hard? Which elements get depth, and why?                                       |\n| Shape language     | Radius scale, notches, steps, pills; whether radii are concentric (inner = outer − padding)                                                   |\n| Typography         | Display and body pairing, scale, weights, tracking, numerals, label case                                                                      |\n| Colour strategy    | Ground and ladder; where the accent may appear; tinted (not black) darks                                                                      |\n| Density and rhythm | Row heights, field heights, spacing scale, hit targets                                                                                        |\n| Component variants | Card, button, tab, table, badge, KPI, top bar and nav; pick a different variant per theme                                                     |\n| Signature objects  | The knurled dial, LED gauge, notch card, glass sheet, banded bars                                                                             |\n| Iconography        | Stroke icons, filled pairs, colour icons, pixel icons, SF-Symbol-like glyphs                                                                  |\n| State physics      | What hover, pressed, selected and focus look like. In Tactile a press sinks; in Pixel the lip collapses; in Liquid the glass lensing changes. |\n\nTwo themes that differ only in hue at a 480px thumbnail count as one theme. Check this on a contact\nsheet (§4.5).\n\n### 4.4 Build the specimen, the states and the dark mode\n\nThe fixture is the Orders screen: KPIs, filter tabs, a table, a detail editor, a notice and an\nactivity feed. It exercises about 30 components in one view. Then add:\n\n- a **state sheet**: rest, hover, pressed, focus, disabled, selected and error for every interactive\n  component;\n- a **designed dark mode**, never an inverted one. A white header on a dark theme is a defect\n  (§4.5).\n\n### 4.5 Self-audit before anyone else looks\n\n1. **Thumbnail test.** On a 4×2 contact sheet at 480px, each theme is identifiable without reading\n   text.\n2. **Dark inversion audit.** Check every dark frame for pale or white surfaces produced by inverting\n   the light scheme: white or light gray headers, slabs and panels, white outlines or shadows, white\n   or pale primary buttons, and pale accent tints used as slabs. Each is a high-severity defect,\n   even when contrast passes. Saturated accent fills are not inversions. Where a theme uses them in\n   dark, and which ink sits on them, is set by the accent policy in that theme's `DESIGN.md`\n   (_Colors_), which is the single authority. An accent policy covers saturated accent fills only:\n   it can never allow a pale or neutral fill, and the ink on every fill must meet the contrast rules\n   in §3.\n3. **Measure pixels, not tokens.** Sample the exported PNG. Two traps make a correct token measure\n   wrong:\n   - a stale stored paint colour on side-specific strokes;\n   - half-pixel positions that split a 1px rule into two faint rows.\n4. **Model audit.** If the theme has a physical model (Tactile's elevation map, Liquid's glass\n   layers), list every node that carries an effect and check that the model justifies each one.\n5. **Guideline audit.** If the style has published guidelines, check every rule. Record which rules\n   are verified upstream and which are your own adopted judgement. For example, the neumorphism\n   guidance Tactile adopted warns against dense tables, small type and many-field forms (adopted\n   local rules, partly unverified upstream).\n\n### 4.6 Independent review, then sign-off\n\n- **Get an independent review.** Ask someone who did not build the theme to check it against these\n  guidelines. The review returns the design changes needed and the evidence still owed, such as\n  missing measurements or states.\n- **Review findings are corrections within the theme's goal.** Apply each one as a local fix to the\n  existing design, and edit approved frames in place. Rebuilding an inspired theme from a spec or a\n  kit turns it into a faithful one; if that is the goal, make it a separate theme (§6).\n- **Then get design sign-off** before the theme ships.\n\n## 5. Anti-patterns\n\n| Anti-pattern                                   | Symptom                                                                                                            | What to do instead                                                                                                                                                                                            |\n| ---------------------------------------------- | ------------------------------------------------------------------------------------------------------------------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| Recolour and re-round the default UI           | The theme looks like the default UI with new colours and radii                                                     | Vary the depth model, shape, type and variants (§4.3)                                                                                                                                                         |\n| Inverted dark mode                             | The dark scheme is the light scheme with colours inverted, and text is hard to read                                | Design the dark: tinted grounds, lighter tinted elevation, dark primaries with accent ink                                                                                                                     |\n| Copying a brand                                | The theme reads as the reference brand, for example Mistral, instead of as its own language                        | Use the idea; derive your own palette                                                                                                                                                                         |\n| Mixing two eras of a platform                  | One screen combines cues from two generations of the same platform                                                 | Keep the two eras distinct. Liquid owns refraction, lensing and the macOS 27 chrome. Cupertino is the Apple-inspired classic composition: blur-only materials, with the floating sidebar and capsule buttons. |\n| Glass with nothing behind it                   | Translucent layers sit on a flat background, so the glass effect is invisible                                      | Put a real desktop, photo or glow behind translucent layers, with specular rims                                                                                                                               |\n| Switching a theme's goal by accident           | An inspired theme rebuilt line by line from a kit loses its identity, or a faithful theme drifts from its platform | Keep each theme's goal and correct within it. A faithful reproduction becomes its own theme (§6)                                                                                                              |\n| Decorative depth                               | Shadows and bevels appear on elements with no consistent reason                                                    | Every shadow must follow the model: pressable things rise, input wells sink                                                                                                                                   |\n| A style used where its guidelines say it fails | The screen uses a pattern the style's own guidelines advise against                                                | Read the style's guidelines and recompose, for example tiles instead of dense tables                                                                                                                          |\n| Imprecise alignment and rhythm                 | Icons sit off-centre in their containers, and regions look cramped                                                 | Centre on whole pixels; space regions generously and consistently                                                                                                                                             |\n| Variations that only change colour             | Flavors are hard to tell apart on a contact sheet                                                                  | Change ground, shapes, sizes and component variants per flavor                                                                                                                                                |\n\n## 6. Theme catalogue\n\nEach theme has a goal:\n\n- **Faithful** themes reproduce a platform's own design language, so an app looks native to it. Use\n  one when the product should feel like part of the platform and needs no brand of its own, for\n  example a Deno desktop app that should look like macOS 27.\n- **Inspired** themes take principles from a platform or a style and build a distinct brand from\n  them. Cupertino borrows Apple's classic cues without copying the official interface.\n- **Own** themes are NetScript's own languages.\n\nChoose by goal; faithful and inspired themes are both valid. Three more faithful themes are planned\n(#2443): macOS 27 (the faithful sibling of Liquid), Apple Classic (of Cupertino) and Fluent 2 Web (a\nweb counterpart to Fluent's Windows 11 desktop).\n\n| Theme              | Family     | Goal     | Thesis                                                                                                                                                                                             | Best for                           | Avoid for             |\n| ------------------ | ---------- | -------- | -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- | ---------------------------------- | --------------------- |\n| Studio (7 flavors) | System     | Own      | A shared component set in seven flavors: Utility, Cloud, Workshop, Playful, Ledger, Atelier, Signal                                                                                                | Any SaaS; the neutral base         | —                     |\n| Tonal              | System     | Faithful | Material 3 Expressive: tonal surfaces and expressive shape                                                                                                                                         | Android-adjacent and consumer apps | —                     |\n| Bloom              | Expressive | Inspired | Widget-first Material You: pastel notch cards, big regular type                                                                                                                                    | Personal dashboards, consumer      | Dense admin           |\n| Cupertino          | Platform   | Inspired | Apple-inspired classic: floating sidebar, large-title header, capsule buttons, inset grouped lists, blur-only materials. A hand-built composition; the faithful version is Apple Classic (planned) | Mac-like tools                     | —                     |\n| Liquid             | Platform   | Inspired | Liquid Glass principles in a NetScript composition, over a real desktop                                                                                                                            | Pro desktop apps                   | Content-heavy reading |\n| Fluent             | Platform   | Faithful | Windows 11 / WinUI: Mica, layers, NavigationView pill                                                                                                                                              | Microsoft-centric enterprise       | —                     |\n| Brutal             | Expressive | Inspired | Gumroad-like flat blocks, black outlines, hard offset shadows                                                                                                                                      | Creator tools, marketing           | Long data sessions    |\n| Filigrane          | Editorial  | Own      | Minimal, thin, legible type with hairline structure                                                                                                                                                | Content, reporting                 | Dense controls        |\n| Terminal           | Developer  | Inspired | A Charm-style TUI on a character grid                                                                                                                                                              | Dev tools, ops                     | Consumer              |\n| Pixel              | Expressive | Inspired | Amber pixel bands, Pixelify Sans, Ore UI lips                                                                                                                                                      | Games, playful products            | Formal finance        |\n| Tactile            | Expressive | Inspired | Guideline-based neumorphism: one material, convex keys, concave wells                                                                                                                              | Commerce consoles, IoT, widgets    | Dense tables          |\n\nEach theme folder, `themes/<id>/`, holds a `DESIGN.md` (the specification) and a `SKILL.md` (how an\nagent builds with the theme).\n\n## 7. Creating a new theme: step by step\n\n1. **Choose the anchor.** Record the anchor in the theme's `DESIGN.md`: sources, licence, what you\n   take, and what you must not copy.\n2. **Write the thesis and three signature moves.**\n3. **Fill in the axes table (§4.3).** Show that at least six axes differ from the nearest existing\n   theme.\n4. **Add the values in Figma.**\n   - Use a Theme mode for the language's values. A new language is a style (§2.4): it also needs its\n     own version of every component, and a role manifest if it adds namespaced roles.\n   - Use density and flavor modes as needed.\n   - Seed bound paints with their resolved colour.\n5. **Build the Orders specimen,** Light and Dark, plus a state sheet. Compose the screen the way the\n   style's guidelines support.\n6. **Run the self-audit (§4.5)** and record the measurements.\n7. **Write `DESIGN.md` and `SKILL.md`** from `themes/_template/`.\n8. **Get an independent review** (§4.6), apply its corrections in place, then get design sign-off.\n9. **Register any new roles in code** (#2414) before the theme ships through registry v2 (#2415).\n   List them in the style's role manifest (§2.4) first.\n\n## 8. Shipping (planned)\n\nNothing in this section ships yet.\n\n- Themes ship as registry v2 items (#2415). Adding a theme installs:\n  - its token CSS and, for a style, its component sources (a registry `style` item);\n  - one co-located skill directory, `.agents/skills/fresh-ui-theme-<id>/`, holding `SKILL.md`,\n    `DESIGN.md` and summaries of the sources `DESIGN.md` references. `SKILL.md` says \"Read\n    `DESIGN.md` in this folder\", so that relative path must resolve in the installed copy.\n\n  An agent working in that app then builds on-theme by default.\n- A consumer skill `netscript-design`, built from this document, ships in the CLI's consumer skill\n  bundle (#2431). The docs site (#2430) publishes the same files in a Design system page group. The\n  skill finds installed themes by skill name (`fresh-ui-theme-<id>`), never by a repository path\n  such as `docs/design-system/themes/`. It must respect the generated-asset chain and the MCP docs\n  budget.\n- The `/create` builder offers only the supported presets and axes in §2.3 and exports the same\n  token set. It must not imply that every gray × accent × theme × flavor × density permutation\n  exists.\n",

  "netscript-operate/SKILL.md": "---\nname: netscript-operate\ndescription: \"Monitor, debug, and analyze a running NetScript application through the NetScript MCP tools. USE FOR: is my app healthy, list recent runs, inspect one execution, find recent errors, why did a job fail, why is a service slow, database/KV bottlenecks, run diagnostics, search the docs. DO NOT USE FOR: scaffolding or changing the project (use netscript-build); Aspire dashboards or raw resource logs (use the aspire skill).\"\n---\n\n# NetScript Operate\n\nObserve a running NetScript app with bounded MCP tools. Every tool returns a summary — chain\ntools, do not dump raw payloads.\n\n## Task → tool\n\n| Task | Tool |\n|---|---|\n| Is the app healthy? | `get_app_status` |\n| List recent executions (jobs, saga instances, trigger firings) | `list_runs` |\n| Inspect one execution end to end | `get_run` |\n| Group recent application errors | `get_recent_errors` |\n| Latest result for a job | `get_last_job_result` |\n| Service performance stats (p50/p95, error rate, throughput) | `analyze_service_performance` |\n| Rank slow/frequent DB + KV operations | `analyze_db_bottlenecks` |\n| Environment + project diagnostics (no running app needed) | `doctor` |\n| Search public docs | `search_docs` |\n| List doc summaries | `list_docs` |\n| Read one doc or section | `get_doc` |\n| Discover CLI verbs | `list_commands` |\n| Run one allowlisted CLI verb | `execute_command` |\n\n## Playbooks\n\n**Is my app healthy?**\n`get_app_status` — one call summarizing services, workers, sagas, triggers, streams with state and\nrecent error counts. Drill into anything unhealthy with `list_runs` or `get_recent_errors`.\n\n**A job failed — find out why.**\n`get_last_job_result` (did it run, what happened) → `get_run` (the failing execution end to end) →\n`get_recent_errors` (correlate with other failures in the same window).\n\n**Service X is slow.**\n`analyze_service_performance` (confirm and quantify: p95, error rate, throughput) →\n`analyze_db_bottlenecks` (if latency is data-bound, rank the slowest KV/DB operations).\n\n**Nothing responds.**\nStart with `doctor` — it checks telemetry reachability, project wiring, Aspire markers, and plugin\ndiagnostics with pass/warn/fail and fix suggestions, and works without a running app. Fix what it\nflags before re-querying telemetry tools.\n\n**A plugin's boundary never runs, or installation succeeded but nothing is wired.** Run\n`netscript plugin doctor` before reading source or hand-probing endpoints. Use\n`.agents/skills/help.md` when you do not yet know whether the symptom belongs to NetScript, Aspire,\nor Deno.\n\n## Docs funnel\n\n`search_docs` (or `list_docs`) to find the right document → `get_doc` with a `section` to read only\nthe relevant part. Never fetch whole pages when a section answers the question.\n\n## Token discipline\n\n- Never print raw tool output to the user — summarize the bounded result.\n- Chain narrow tools instead of re-running broad ones.\n- Prefer `doctor` for setup problems over hand-probing endpoints.\n\n## Boundaries\n\n- No project mutation here — scaffold, add, and generate live in `netscript-build`.\n- For Aspire dashboards, resource start/stop, and raw traces/logs, use the `aspire` skill.\n",

  "netscript/SKILL.md": "---\nname: netscript\ndescription: 'Router for operating and building NetScript applications. USE FOR: scaffold a NetScript app, add services/plugins/UI, theme the app and its page chrome, route renaming/moving and router.ts reconciliation, run the database lifecycle, monitor services/jobs/sagas/triggers/streams, debug a failing run, analyze service or database performance, search NetScript documentation. DO NOT USE FOR: generic Deno language/tooling questions (use the deno skill); Aspire orchestration, dashboards, or resource graph specifics (use the aspire skill); non-NetScript projects. INVOKES: the `netscript` CLI and the NetScript MCP tools (get_app_status, list_runs, get_run, doctor, search_docs, list_commands, execute_command, ...).'\n---\n\n# NetScript Skill (router)\n\nNetScript ships one version-locked agentic surface: the `netscript` CLI, the NetScript MCP tools,\nand these skills share one vocabulary. This router only dispatches — **it is not useful alone.**\nPick a workflow skill below and follow its tables.\n\nBefore implementing an unfamiliar NetScript API or architecture, call MCP `find_guidance` with the\ntask. Use `search_docs` for literal lookup and `get_doc` for exact retrieval.\n\n## Routing\n\n| The task is about...                                                                                                                   | Go to                   |\n| -------------------------------------------------------------------------------------------------------------------------------------- | ----------------------- |\n| Scaffold, add resources, theme the app, rename/move routes, reconcile router.ts, database lifecycle, generators — changing the project | `netscript-build`       |\n| Health, failing runs, slow services, error triage, docs lookup — observing the project                                                 | `netscript-operate`     |\n| Aspire orchestration, resource health, logs, spans, or traces                                                                          | `aspire`                |\n| Deno runtime, type checking, permissions, or module resolution                                                                         | `deno`                  |\n| Something hangs, vanishes, or stays silent and the cause is unclear                                                                    | [`help.md`](../help.md) |\n| Theme choice, visual design, compatible on-theme UI and design self-audit                                                              | `netscript-design`      |\n\n## CLI vs MCP\n\n- **Prefer the CLI** when a CLI verb covers the task (scaffold, add, generate, migrate, seed).\n  Mutations must behave exactly like a user-run command.\n- **Use MCP tools** for telemetry-heavy or interactive loops: monitoring, debugging, performance\n  analysis, and documentation search, where one bounded call replaces many token-heavy queries.\n- Discover the real verb surface at runtime with the `list_commands` MCP tool rather than guessing\n  flags; run allowlisted verbs through `execute_command`.\n\n## Hand-offs\n\n| Need                                                               | Skill                   |\n| ------------------------------------------------------------------ | ----------------------- |\n| Aspire start/stop, dashboard, resource graph, raw traces/logs      | `aspire`                |\n| Generic Deno runtime / tooling questions                           | `deno`                  |\n| Unexplained hang, vanish, silence, or “Healthy but not responding” | [`help.md`](../help.md) |\n\nWhen the symptom is unclear—something hangs, vanishes, or silently does nothing—start with\n`.agents/skills/help.md`. It routes from the failure to the first diagnostic command.\n\nNetScript's MCP layer is framework-semantic (jobs, sagas, triggers, streams, workers, docs, CLI\nverbs); it rides above Aspire's generic MCP, it does not replace it.\n",
};

/** SHA-256 of canonical manifest-ordered skill paths and content. */
export const EMBEDDED_SKILL_BUNDLE_HASH: string = new Uint8Array(
  await crypto.subtle.digest(
    'SHA-256',
    new TextEncoder().encode(
      (JSON.parse(EMBEDDED_SKILL_FILES['manifest.json']) as { files: string[] }).files.map((path) =>
        `${path}␀${EMBEDDED_SKILL_FILES[path]}`
      ).join('␀'),
    ),
  ),
).toHex();
